window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch06"]={"id": "ch06", "title": "第六章 转录组学", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第六章 转录组学", "slides": [{"i": 0, "sec": "第一节 转录组学概述", "title": "转录组学概述与中心法则", "notes": "本页为第六章开篇，首先回顾中心法则：DNA 通过转录将遗传信息传递给 RNA，RNA 再通过翻译传递给蛋白质，该法则由 Crick 于 1958 年提出。中心法则对应三个组学层次：基因组学（DNA）、转录组学（RNA）和蛋白质组学（蛋白质）。转录组学从 RNA 水平研究基因表达调控机制，系统揭示细胞中基因转录调控规律。本章提要指出，内容涵盖转录组学的产生、发展及最新研究策略，包括试验设计、测序流程、数据处理和功能分析，重点为 RNA-seq 数据分析，如质控、比对、表达定量、差异表达分析、聚类分析及共表达网络等，并拓展可变剪切、基因融合和多组学分析，最后以拟南芥脱落酸响应为例进行实践。第一节为转录组学概述，强调细胞是生命活动基本单元，DNA 是遗传信息载体，蛋白质是功能执行者，RNA 是信息传递媒介。", "page": 102, "level": "掌握", "img": "assets/img/ch06/p102.jpg", "anim": null, "fig": null, "points": ["中心法则：DNA→RNA→蛋白质，由Crick于1958年提出", "三个组学层次：基因组学(DNA)、转录组学(RNA)、蛋白质组学(蛋白质)", "转录组学从RNA水平研究基因表达调控机制", "本章涵盖转录组学产生、转录本测定技术、数据分析及功能分析"], "check": {"q": "中心法则由Crick于哪一年提出，并对应基因组学、转录组学和蛋白质组学三个组学层次？", "o": ["A. 1953年", "B. 1958年", "C. 1970年", "D. 1995年"], "a": "B", "e": "第六章开篇回顾中心法则时指出，该法则由Crick于1958年提出，对应DNA、RNA和蛋白质三个组学层次。"}, "cards": [{"front": "中心法则由谁提出？对应哪三个组学层次？", "back": "Crick于1958年提出；对应基因组学(DNA)、转录组学(RNA)、蛋白质组学(蛋白质)。", "mnemonic": "DNA→RNA→蛋白质，三组学对应。", "useImg": false}]}, {"i": 1, "sec": "第一节 转录组学概述", "title": "转录组学的产生与转录本测定技术", "notes": "本页继续第一节，介绍转录组学发展历史：早期研究报道人脑组织 609 条 mRNA 序列，为转录组研究首次尝试；1995 年 Velculescu 等获得酵母全转录组；2008 年发布人类全转录组数据，揭示数百万转录本。转录组广义指细胞中所有 RNA 分子总和，包括 mRNA、rRNA、tRNA、ncRNA 等，有时特指 mRNA；本章无特殊说明时转录本专指 mRNA。转录本作为连接基因和蛋白质的桥梁，反映特定时空下基因表达情况。第二部分介绍转录本测定研究：早期基于实验的技术如 Northern blotting 和 RT-PCR 精准但通量低、价格高；1980 年后 Sanger 测序用于 EST 文库测定转录本；随后出现 SAGE、CAGE、MPSS 等基于 Sanger 测序的技术，通量更高并具备一定定量能力，但受第一代测序限制。", "page": 103, "level": "理解", "img": "assets/img/ch06/p103.jpg", "anim": null, "fig": null, "points": ["早期研究：人脑组织609条mRNA序列为首次尝试", "1995年Velculescu等获得酵母全转录组", "2008年发布人类全转录组数据，揭示数百万转录本", "转录组广义指所有RNA分子总和，包括mRNA、rRNA、tRNA、ncRNA等，有时特指mRNA"], "check": {"q": "关于转录组学发展历史，下列哪项描述正确？", "o": ["A. 1995年Velculescu等获得人脑全转录组", "B. 早期研究报道人脑组织609条mRNA序列，是转录组研究首次尝试", "C. 2008年发布酵母全转录组数据", "D. 本章无特殊说明时转录本专指rRNA"], "a": "B", "e": "早期研究报道人脑组织609条mRNA序列，为转录组研究首次尝试；1995年Velculescu等获得酵母全转录组；2008年发布人类全转录组数据；本章无特殊说明时转录本专指mRNA。"}, "cards": [{"front": "转录组的广义和狭义定义是什么？", "back": "广义：细胞中所有RNA分子总和，包括mRNA、rRNA、tRNA、ncRNA等；狭义：特指mRNA。", "mnemonic": "广义所有RNA，狭义专指mRNA。", "useImg": false}]}, {"i": 2, "sec": "第一节 转录组学概述", "title": "RNA-seq 应用：差异表达与可变剪切", "notes": "本页介绍 RNA-seq 技术应用进展。差异表达分析旨在找出不同条件下表达上调、下调或稳定的基因，探究实验条件如何影响基因表达及调控机制。应用方向包括实验处理、野生型与突变型、正常组织与瘤变组织、环境刺激响应、免疫应答等比较。例如 Yang 等对油菜全基因组测序，通过 RNA-seq 发现异源多倍体油菜亚基因组间存在同源异体表达优势，差异表达基因比中性基因具有更多选择潜力，促进硫代葡萄糖苷和脂质代谢基因选择。需注意差异表达分析仅筛选候选基因，是否真正参与调控仍需后续验证。可变剪切（选择性剪切）指 mRNA 前体通过不同剪切方式连接外显子形成成熟 mRNA，一个基因可产生多条转录本即异构体，增加蛋白质多样性但使调控机制更复杂。RNA-seq 可识别可变剪切位点、鉴定异构体。例如 Zhang 等分析发育中大脑皮层神经祖细胞和神经元 RNA-seq 数据，发现数百个可变剪切事件。", "page": 104, "level": "掌握", "img": "assets/img/ch06/p104.jpg", "anim": null, "fig": null, "points": ["差异表达分析：找出不同条件下表达上调、下调或稳定的基因", "应用方向：实验处理、野生型与突变型、正常与瘤变组织、环境刺激、免疫应答等", "案例：Yang等对油菜全基因组测序，发现异源多倍体亚基因组间同源异体表达优势"], "check": {"q": "关于RNA-seq差异表达分析，下列哪项正确？", "o": ["A. 差异表达分析可直接证明基因功能", "B. 差异表达分析仅筛选候选基因，还需后续验证", "C. 差异表达分析只能用于正常组织与瘤变组织比较", "D. Yang等发现异源多倍体油菜亚基因组间不存在同源异体表达优势"], "a": "B", "e": "差异表达分析旨在找出不同条件下表达上调、下调或稳定的基因，但仅筛选候选基因，不能直接证明功能；Yang等发现异源多倍体油菜亚基因组间存在同源异体表达优势。"}, "cards": [{"front": "差异表达分析的应用方向有哪些？", "back": "实验处理、野生型与突变型、正常组织与瘤变组织、环境刺激响应、免疫应答等比较。", "mnemonic": "处理、突变、瘤变、环境、免疫。", "useImg": false}]}, {"i": 3, "sec": "第一节 转录组学概述", "title": "RNA-seq 试验设计与测序流程", "notes": "本页进入第二节试验设计和测序流程。RNA-seq 实验目的是为生物学问题提供思路和证据，严密设计和规范操作是成功首要条件。实验前需考虑：一、生物学重复：无重复难以排除随机误差，降低统计推断可靠性；过多重复增加成本，一般建议 3~5 个，假阳性控制要求高时可适当增加。二、样本提取：原则是控制干扰变量及避免人为误差，注意提取时间、组织细胞控制及提取后及时冷冻保存。三、测序深度：有参考基因组且不分析可变剪切或新转录本时，每样本最少 5M 有效 reads 可满足要求（ENCODE 推荐）；鉴定新转录本或无参考基因组时需增加深度；small RNA 一般需 30M 以上有效匹配 reads。四、文库构建：分链特异性与非链特异性文库，非链特异性无法区分正义链或反义链，链特异性保留转录本方向信息，避免互补链干扰，具有基因表达定量和可变剪切分析优势。", "page": 105, "level": "掌握", "img": "assets/img/ch06/p105.jpg", "anim": null, "fig": null, "points": ["实验目的：为生物学问题提供思路和证据，严密设计和规范操作是成功首要条件", "生物学重复：一般建议3~5个，假阳性控制要求高时可适当增加", "样本提取原则：控制干扰变量及避免人为误差，注意提取时间、组织细胞控制及提取后及时冷冻保存"], "check": {"q": "RNA-seq试验设计中，关于生物学重复和测序深度的建议，下列哪项正确？", "o": ["A. 一般建议1~2个重复即可", "B. 一般建议3~5个重复，假阳性控制要求高时可适当增加", "C. 有参考基因组且不分析可变剪切时，每样本最少1M有效reads", "D. 重复越多越好，无需考虑成本"], "a": "B", "e": "RNA-seq试验设计一般建议3~5个生物学重复，假阳性控制要求高时可适当增加；有参考基因组且不分析可变剪切或新转录本时，每样本最少5M有效reads。"}, "cards": [{"front": "RNA-seq实验设计中生物学重复一般建议多少个？", "back": "一般建议3~5个，假阳性控制要求高时可适当增加。", "mnemonic": "3~5个重复，严控假阳可增加。", "useImg": false}]}, {"i": 4, "sec": "第一节 转录组学概述", "title": "测序平台比较与 RNA-seq 文库制备", "notes": "本页继续第二节。测序平台选择依赖实验及后续分析需要，考虑读长、最大通量、准确率等指标。表 6-2 比较常用平台：454（2005 年，读长 700 bp，通量 0.7 Gbp，准确率 99.9%）、Illumina（2006 年，读长 50~300 bp，通量 900 Gbp，准确率 99.9%）、SOLiD（2008 年，读长 50 bp，通量 320 Gbp，准确率 99.9%）、Ion Torrent（2010 年，读长 400 bp，通量 30 Gbp，准确率 98%）。RNA-seq 文库制备流程：选择样本提取 RNA，采用 PolyA 富集或 rRNA 移除策略分离纯化 RNA，随机打碎成短片段并反转录为 cDNA，选择合适长度片段添加接头构建文库，扩增并测序。图 6-2 展示流程：目标样本 RNA 分离纯化、cDNA 文库构建、比对到参考基因组或转录组、识别可变剪切区域等。cDNA 文库制备关键步骤包括总 RNA 提取：将 RNA 从组织分离并与 DNase 混合降解 DNA，然后用凝胶和毛细管电泳检测质量。", "page": 106, "level": "理解", "img": "assets/img/ch06/p106.jpg", "anim": null, "fig": "表6-2比较常用测序平台，查看各平台的读长、通量、准确率等指标，根据实验需求选择合适平台。", "points": ["测序平台选择依赖实验及后续分析需要，考虑读长、最大通量、准确率等指标", "454：2005年，读长700 bp，通量0.7 Gbp，准确率99.9%", "Illumina：2006年，读长50~300 bp，通量900 Gbp，准确率99.9%", "SOLiD：2008年，读长50 bp，通量320 Gbp"], "check": {"q": "根据表6-2，下列测序平台与其读长、通量对应正确的是？", "o": ["A. 454：读长700 bp，通量0.7 Gbp", "B. Illumina：读长700 bp，通量900 Gbp", "C. SOLiD：读长400 bp，通量320 Gbp", "D. Ion Torrent：读长50 bp，通量0.7 Gbp"], "a": "A", "e": "454读长700 bp、通量0.7 Gbp；Illumina读长50~300 bp、通量900 Gbp；SOLiD读长50 bp、通量320 Gbp；Ion Torrent读长400 bp。"}, "cards": [{"front": "常用测序平台454、Illumina、SOLiD的读长和通量分别是多少？", "back": "454：读长700 bp，通量0.7 Gbp；Illumina：读长50~300 bp，通量900 Gbp；SOLiD：读长50 bp，通量320 Gbp。", "mnemonic": "454长读低通量，Illumina高通量，SOLiD短读。", "useImg": false}]}, {"i": 5, "sec": "第一节 转录组学概述", "title": "rRNA 移除、cDNA 合成与 FASTQ 格式", "notes": "本页继续第二节并进入第三节。rRNA 移除原理：rRNA 占总 RNA 比例超过 90%，移除可去除大部分无关转录本，留下目标序列。cDNA 合成：RNA 无法直接测序，需打碎成片段并逆转录为 cDNA；打碎可采用酶、超声波或喷雾器；片段化降低随机引物逆转录的 5' 偏好和引物结合位点影响，但降低 5' 和 3' 端转化为 DNA 效率。逆转录会导致方向性缺失，通过化学标记可保留原转录本方向信息（链特异性文库）。短片段末端修复加接头，按长度排序分类，选择适当长度 PCR 扩增纯化，检测文库质量后上机测序。cDNA 文库制备是 RNA-seq 前置关键步骤，高质量 mRNA 是首要条件，mRNA 易被 RNA 酶降解，提取时需防止 RNA 酶污染。第三节转录组数据核心分析开始：第二代测序得到 50~250 bp 短片段称为 reads，原始结果以 FASTQ 文件存储，FASTQ 是存储生物序列及测序质量得分的文本文件，序列字母和质量得分用单个 ASCII 字符表示，最初由 Wellcome Trust Sanger 研究所开发。", "page": 107, "level": "掌握", "img": "assets/img/ch06/p107.jpg", "anim": null, "fig": null, "points": ["rRNA移除原理：rRNA占总RNA比例超过90%，移除可去除大部分无关转录本", "cDNA合成：RNA无法直接测序，需打碎成片段并逆转录为cDNA", "片段化降低随机引物逆转录的5'偏好和引物结合位点影响，但降低5'和3'端转化为DNA效率", "逆转录会导致方向性缺失"], "check": {"q": "关于rRNA移除、cDNA合成与FASTQ格式，下列哪项正确？", "o": ["A. rRNA占总RNA比例低于10%，通常无需移除", "B. RNA可直接测序，无需逆转录", "C. rRNA占总RNA比例超过90%，移除可去除大部分无关转录本", "D. 链特异性文库会丢失原转录本方向信息"], "a": "C", "e": "rRNA占总RNA比例超过90%，移除可去除大部分无关转录本；RNA无法直接测序，需逆转录为cDNA；通过化学标记可保留原转录本方向信息，构建链特异性文库。"}, "cards": [{"front": "为什么需要移除rRNA？cDNA合成中片段化的作用是什么？", "back": "rRNA占总RNA比例超过90%，移除可去除大部分无关转录本；片段化降低随机引物逆转录的5'偏好和引物结合位点影响，但降低5'和3'端转化为DNA效率。", "mnemonic": "rRNA占90%需移除；片段化降偏好但降效率。", "useImg": false}]}, {"i": 6, "sec": "第三节 转录组数据核心分析", "title": "测序数据质量控制与FastQC评估", "notes": "本页属于第三节转录组数据核心分析，介绍RNA-seq测序完成后对原始数据进行质量评估的必要性。测序质量直接影响后续比对、定量和差异表达分析的可靠性，因此需先检查GC含量、序列重复程度、接头污染等指标。常用工具为FastQC，适用于Illumina平台；NGSQC则适用于所有测序平台。FastQC报告通常关注Per base sequence quality（各碱基位置质量值）、Per base sequence content（碱基组成偏好）、Per sequence GC content（GC分布是否偏离理论分布）以及Sequence Duplication levels（重复序列比例）等模块。图中以“√”表示质量达标，“!”表示轻微异常，“×”表示严重失常。若评估结果异常，可采取去接头、过滤低质量reads、截短序列（如切除起始端接头或低质量区）等处理，常用工具包括FASTX-Toolkit和Trimmomatic。处理后若质量仍差，应慎重决定该样本是否进入后续分析。", "page": 108, "level": "掌握", "img": "assets/img/ch06/p108.jpg", "anim": null, "fig": null, "points": ["测序质量直接影响后续比对、定量和差异表达分析的可靠性", "需检查GC含量、序列重复程度、接头污染等指标", "常用工具：FastQC适用于Illumina平台；NGSQC适用于所有测序平台", "FastQC报告关注Per base sequence quality等指标"], "check": {"q": "关于测序数据质量控制与FastQC评估，下列哪项正确？", "o": ["A. FastQC适用于所有测序平台", "B. NGSQC仅适用于Illumina平台", "C. FastQC常用于Illumina平台，NGSQC适用于所有测序平台", "D. 测序质量不影响后续比对和定量分析"], "a": "C", "e": "FastQC常用于Illumina平台，NGSQC则适用于所有测序平台；测序质量直接影响后续比对、定量和差异表达分析的可靠性。"}, "cards": [{"front": "FastQC和NGSQC分别适用于什么平台？", "back": "FastQC适用于Illumina平台；NGSQC适用于所有测序平台。", "mnemonic": "FastQC专Illumina，NGSQC通吃。", "useImg": false}]}, {"i": 7, "sec": "第三节 转录组数据核心分析", "title": "剪接比对与SAM文件格式", "notes": "本页继续第三节内容，重点讲解剪接比对（spliced alignment）和比对文件格式。由于真核生物mRNA的reads可能跨越外显子-外显子连接处，而参考基因组中包含内含子，因此reads在剪接位点附近会被内含子隔开，需要剪接比对工具将reads分段比对到剪接点两侧的外显子上。常用工具包括TopHat、STAR和HISAT；其中TopHat2先利用Bowtie将reads比对到全基因组，成功匹配区域用于构建潜在剪接体结构，未匹配reads再建立索引并比对到剪接区域以寻找剪接位点。HISAT是TopHat的优化版，采用BWT/FM索引建立全局和局部索引，内存占用更少，速度和精度更高。此外，GSNAP和MapSplice等工具在剪接比对基础上针对SNP鉴定进行了优化。比对结果通常以SAM（sequence alignment map）格式存储，由标题部分和对齐结果部分组成，是后续reads计数和转录本定量的基础输入。", "page": 109, "level": "掌握", "img": "assets/img/ch06/p109.jpg", "anim": null, "fig": null, "points": ["剪接比对：真核生物mRNA的reads可能跨越外显子-外显子连接处，需剪接比对工具", "常用工具：TopHat、STAR、HISAT", "TopHat2先利用Bowtie进行比对", "SAM文件格式用于存储比对结果"], "check": {"q": "关于剪接比对与SAM文件格式，下列哪项正确？", "o": ["A. 真核生物mRNA的reads不会跨越外显子-外显子连接处", "B. 剪接比对工具可将reads分段比对到剪接点两侧的外显子上", "C. TopHat、STAR和HISAT均不能进行剪接比对", "D. SAM文件不是比对结果格式"], "a": "B", "e": "由于真核生物mRNA的reads可能跨越外显子-外显子连接处，需要剪接比对工具将reads分段比对到剪接点两侧的外显子上；常用工具包括TopHat、STAR和HISAT。"}, "cards": [{"front": "为什么需要剪接比对？常用工具哪些？", "back": "真核生物mRNA的reads可能跨越外显子-外显子连接处，需剪接比对工具将reads分段比对到剪接点两侧的外显子上；常用工具：TopHat、STAR、HISAT。", "mnemonic": "跨外显子需剪接比对，TopHat、STAR、HISAT。", "useImg": false}]}, {"i": 8, "sec": "第三节 转录组数据核心分析", "title": "比对评估与基于reads计数的转录本定量", "notes": "本页属于第三节，首先介绍比对结果评估：可通过reads在参考基因组上的分布评估RNA打断随机性，分布均匀说明打断随机性较好；匹配reads的GC含量与PCR偏差有关。常用评估工具有RSeQC和Qualimap。随后进入基于第二代测序的转录本定量。相比基因芯片，RNA-seq通量更高、不依赖已知探针、可检测全转录组且对低丰度转录本更灵敏，通常利用匹配到转录本的reads数估算表达量。reads计数按多重比对处理方式分为两类：一是只保留唯一匹配reads，舍弃多重比对reads，常用于基因水平计数，工具如HTSeq-count和featureCounts，输入需要SAM文件和GTF注释文件；二是保留多重匹配reads，利用统计模型将其分配到对应转录本异构体上，工具如Cufflinks、StringTie和RSEM。由于reads数受基因长度、测序深度和测序误差影响，需进行标准化，常用策略包括RPKM、FPKM和TPM等。", "page": 110, "level": "掌握", "img": "assets/img/ch06/p110.jpg", "anim": null, "fig": null, "points": ["比对结果评估：通过reads在参考基因组上的分布评估RNA打断随机性，分布均匀说明打断随机性较好", "匹配reads的GC含量与PCR偏差有关", "常用评估工具：RSeQC和Qualimap", "RNA-seq相比基因芯片通量更高、不依赖已知探针、可检测全转录组且对低丰度转录本更灵敏"], "check": {"q": "关于比对评估与基于reads计数的转录本定量，下列哪项正确？", "o": ["A. reads在参考基因组上分布均匀说明RNA打断随机性较差", "B. 匹配reads的GC含量与PCR偏差无关", "C. RSeQC和Qualimap可用于比对结果评估", "D. RNA-seq依赖已知探针，不能检测低丰度转录本"], "a": "C", "e": "RSeQC和Qualimap常用于比对结果评估；reads分布均匀说明打断随机性较好；匹配reads的GC含量与PCR偏差有关；RNA-seq不依赖已知探针，对低丰度转录本更灵敏。"}, "cards": [{"front": "如何评估RNA打断随机性？常用评估工具有哪些？", "back": "通过reads在参考基因组上的分布评估，分布均匀说明打断随机性较好；常用工具：RSeQC和Qualimap。", "mnemonic": "分布均匀打断好，RSeQC和Qualimap。", "useImg": false}]}, {"i": 9, "sec": "第三节 转录组数据核心分析", "title": "标准化策略与转录组核心分析策略选择", "notes": "本页继续第三节，先补充标准化与差异表达分析的关系。edgeR采用的TMM校正方法通过去除高表达和高差异基因后计算加权系数，使剩余基因校正后差异倍数尽可能小，结果较稳定，但未校正基因长度影响，且不同样本比较会得到不同表达值，不利于共表达等整合分析。随后介绍转录组核心分析策略选择：根据有无参考信息分为有参分析和无参分析，有参分析又分为参考基因组分析和参考转录组分析。若有参考基因组且需研究可变剪接或识别新转录本，应将reads比对到参考基因组，可选用TopHat、HISAT、STAR等剪接比对软件，再用Cufflinks、StringTie进行转录本拼接，与基因组注释GFF文件比较鉴定新转录本，并用Blast2GO等进行功能注释。若有全转录组且只关注已知转录本表达，可将reads通过Bowtie等非剪接比对软件直接匹配到参考转录组，再用RSEM、Kallisto等定量。图中展示了基于参考基因组、参考转录组和无参考信息的主要分析流程。", "page": 111, "level": "掌握", "img": "assets/img/ch06/p111.jpg", "anim": null, "fig": null, "points": ["edgeR采用的TMM校正方法通过去除高表达和高差异基因后计算加权系数，使剩余基因校正后差异倍数尽可能小", "TMM未校正基因长度影响，且不同样本比较会得到不同表达值，不利于共表达等整合分析", "转录组核心分析策略选择：根据有无参考信息分为有参分析和无参分析", "有参分析又分为参考基因组分析和参考转录组分析"], "check": {"q": "关于标准化策略与转录组核心分析策略选择，下列哪项正确？", "o": ["A. edgeR采用的TMM校正方法未校正基因长度影响", "B. TMM校正后不同样本比较会得到相同表达值", "C. 有参考基因组且需研究可变剪接时，应将reads比对到参考转录组", "D. 无参考信息时不能进行转录组分析"], "a": "A", "e": "edgeR采用的TMM校正方法未校正基因长度影响，且不同样本比较会得到不同表达值；有参考基因组且需研究可变剪接或识别新转录本时，应将reads比对到参考基因组；无参考信息时可采用从头组装。"}, "cards": [{"front": "edgeR的TMM校正方法有何优缺点？", "back": "优点：通过去除高表达和高差异基因后计算加权系数，使剩余基因校正后差异倍数尽可能小，结果较稳定；缺点：未校正基因长度影响，且不同样本比较会得到不同表达值，不利于共表达等整合分析。", "mnemonic": "TMM稳定但不校长度，样本间值不同。", "useImg": false}]}, {"i": 10, "sec": "第三节 转录组数据核心分析", "title": "无参从头组装与功能分析概述", "notes": "本页先完成第三节无参分析流程：无参考信息时可采用Trinity进行从头组装，其核心包括Inchworm、Chrysalis和Butterfly三个步骤。Inchworm将RNA-seq原始reads切割为k-mer并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图，依据reads和配对reads寻找最佳路径，得到具有可变剪接的全长转录本。由于第二代测序读长限制，从头组装可能存在问题，需从完整性、准确性和冗余度评估组装质量。之后可将reads用Bowtie回贴到组装转录本，用HTSeq-count或RSEM计数估算表达量，并用Blast2GO进行功能注释，作为Unigene参考注释。随后进入第四节功能分析，指出核心分析只是初步处理，要挖掘生物学机制还需差异表达分析、聚类分析、共表达网络构建、GO和Pathway富集等，此外RNA-seq还可用于可变剪接、基因融合及多组学结合分析。", "page": 112, "level": "理解", "img": "assets/img/ch06/p112.jpg", "anim": null, "fig": null, "points": ["无参考信息时可采用Trinity进行从头组装", "Trinity核心包括Inchworm、Chrysalis和Butterfly三个步骤", "Inchworm将RNA-seq原始reads切割为k-mer并延伸组装成contigs", "Chrysalis将contigs聚类并构建de Bruijn图", "Butterfly拆分de Bruijn图，依据reads"], "check": {"q": "关于无参从头组装与功能分析概述，下列哪项正确？", "o": ["A. Trinity核心步骤包括Inchworm、Chrysalis和Butterfly", "B. Inchworm将contigs聚类并构建de Bruijn图", "C. Chrysalis将RNA-seq原始reads切割为k-mer并延伸组装成contigs", "D. Butterfly拆分de Bruijn图后不能得到可变剪接转录本"], "a": "A", "e": "Trinity核心包括Inchworm、Chrysalis和Butterfly；Inchworm将reads切割为k-mer并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图，依据reads和配对reads寻找最佳路径，得到具有可变剪接的全长转录本。"}, "cards": [{"front": "Trinity从头组装的三个核心步骤是什么？", "back": "Inchworm、Chrysalis和Butterfly。Inchworm将reads切割为k-mer并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图，依据reads。", "mnemonic": "Inchworm、Chrysalis、Butterfly。", "useImg": false}]}, {"i": 11, "sec": "第三节 转录组数据核心分析", "title": "差异表达分析的统计分布与常用工具比较", "notes": "本页属于第四节功能分析中的差异表达分析。差异表达分析基于统计学模型，判断不同样本处理下的基因表达差异是源于处理效应还是随机误差，样本选取对结果至关重要。页中重点比较几种reads频数分布模型：泊松分布假设均值等于方差，但实际基因表达方差常远大于均值；负二项分布通过散度因子调节离散度，更符合实际情况，DESeq和edgeR均采用负二项分布。β负二项分布可拟合多重比对reads分配误差，与负二项分布结合，Cuffdiff采用该分布。图6-7展示真实样本中基因表达方差与均值的关系，说明DESeq和edgeR比泊松分布更能反映真实情况。常用工具比较方面，limma在多数实验中表现良好且速度快；DESeq和edgeR在显著性排序上与limma相似，但FDR控制可能偏宽松；SAMseq在FDR控制上表现良好，但通常需要10个以上生物学重复才能达到可接受的检测灵敏度；NOISeq等工具适用于特定实验设计。工具选择需结合重复数和表达水平。", "page": 113, "level": "掌握", "img": "assets/img/ch06/p113.jpg", "anim": null, "fig": null, "points": ["差异表达分析基于统计学模型，判断基因表达差异是源于处理效应还是随机误差", "泊松分布假设均值等于方差，但实际基因表达方差常远大于均值", "负二项分布通过散度因子调节离散度，更符合实际情况，DESeq和edgeR均采用负二项分布", "β负二项分布可拟合多"], "check": {"q": "关于差异表达分析的统计分布与常用工具比较，下列哪项正确？", "o": ["A. 泊松分布假设均值等于方差，但实际基因表达方差常远大于均值", "B. 负二项分布假设均值等于方差", "C. DESeq和edgeR均采用泊松分布", "D. Cuffdiff采用泊松分布"], "a": "A", "e": "泊松分布假设均值等于方差，但实际基因表达方差常远大于均值；负二项分布通过散度因子调节离散度，更符合实际，DESeq和edgeR均采用负二项分布；Cuffdiff采用β负二项分布。"}, "cards": [{"front": "为什么负二项分布比泊松分布更适合差异表达分析？", "back": "泊松分布假设均值等于方差，但实际基因表达方差常远大于均值；负二项分布通过散度因子调节离散度，更符合实际情况，DESeq和edgeR均采用负二项分布。", "mnemonic": "泊松均值等方差，负二项更实际。", "useImg": false}]}, {"i": 12, "sec": "第四节 功能分析", "title": "差异表达分析工具比较与单基因分析局限", "notes": "本页以表6-3汇总了截至2017年10月常用差异表达分析工具，包括edgeR、DESeq2、baySeq、NOISeq、limma、Cuffdiff2、EBSeq等，并列出其版本、标准化方式、模型假设和统计检验方法。标准化方式有TMM、upper quartile、RLE、DESeq sizeFactors、RPKM/FPKM、quantile等；模型假设包括负二项分布、非参数、经验贝叶斯、voom转换等；统计检验包括exact test、Wald test、LRT、t-test等。差异表达分析可初步筛选处理条件引起的差异基因，但结果受显著性阈值和差异倍数阈值影响很大。由于多重检验，需用BH方法将P值校正为q值或FDR，通常以FDR<0.05、|log2FC|>1为界限，也可根据结果多少调整阈值。差异表达分析得到的是相互独立的基因，直接进行单基因分析存在工作量大、忽略基因间相互作用、生物学过程解释不可靠等弊端。因此需要进一步对差异基因进行功能分析，如聚类、富集分析和共表达网络分析。", "page": 114, "level": "掌握", "img": "assets/img/ch06/p114.jpg", "anim": null, "fig": "表6-3列出各差异表达分析工具的版本、标准化方式、模型假设和统计检验方法，可根据数据特点选择合适工具。", "points": ["表6-3汇总了截至2017年10月常用差异表达分析工具，包括edgeR、DESeq2、baySeq、NOISeq、limma、Cuffdiff2、EBSeq等", "标准化方式有TMM、upper quartile、RLE、DESeq sizeFactors、RPKM/FPKM、quantile等", "模型假设包括泊松分布、负二项分布等", "统计检验方法包括精确检验、广义线性模型等"], "check": {"q": "关于差异表达分析工具比较与单基因分析局限，下列哪项正确？", "o": ["A. 表6-3汇总的工具均采用相同标准化方式和模型假设", "B. edgeR、DESeq2、baySeq等工具在标准化方式、模型假设和统计检验上存在差异", "C. 单基因分析不存在局限性", "D. limma采用负二项分布"], "a": "B", "e": "表6-3汇总的edgeR、DESeq2、baySeq、NOISeq、limma、Cuffdiff2、EBSeq等工具在标准化方式、模型假设和统计检验方法上存在差异；单基因分析存在局限，需结合功能分析。"}, "cards": [{"front": "常用差异表达分析工具有哪些？标准化方式有哪些？", "back": "工具：edgeR、DESeq2、baySeq、NOISeq、limma、Cuffdiff2、EBSeq等；标准化方式：TMM、upper quartile、RLE、DESeq sizeFactors、RPKM/FPKM、quantile等。", "mnemonic": "edgeR、DESeq2等；TMM、RLE等。", "useImg": false}]}, {"i": 13, "sec": "第四节 功能分析", "title": "K-means聚类过程与层次聚类", "notes": "本页介绍基因表达数据的功能分析中的聚类方法。图6-8展示K-means聚类过程：先初始化质心，设定质心，初次归类，再重新计算质心，再次归类，再次计算质心，迭代直至收敛。K-means将基因划分为K个簇，使簇内基因表达模式相似。层次聚类按方向分为聚集型和分裂型，常用凝聚型层次聚类。其策略是：将每个基因作为一个初始簇，成对计算基因间距离，合并距离最小的两个簇，重新计算新簇与所有原始簇的距离，重复直至所有基因包含在一个簇中。图6-9为典型基因层次聚类树，可根据分支长度阈值将基因聚到不同模块。基于拓扑覆盖矩阵差异性的基因聚类也被提及。自组织映射SOM是一种神经网络聚类算法，通过无监督学习将高维输入空间降维映射到2维平面。SOM思想来自人脑神经元自组织排列，即对特定外界信号敏感的神经元组织形式是后天接受信息输入后训练而成。SOM模拟不同区域神经元对应不同功能，通过最优参考矢量集合对输入模式聚类。训练时随机选取样本，寻找响应最强烈的获胜神经元，再以获胜神经元为中心更新邻近区域神经元权值，邻域范围逐渐缩小。", "page": 115, "level": "掌握", "img": "assets/img/ch06/p115.jpg", "anim": null, "fig": "图6-8展示K-means聚类过程，观察质心初始化和迭代更新过程，理解聚类收敛条件。", "points": ["K-means聚类过程：初始化质心，设定质心，初次归类，重新计算质心，再次归类，迭代直至收敛", "K-means将基因划分为K个簇，使簇内基因表达模式相似", "层次聚类按方向分为聚集型和分裂型，常用凝聚型层次聚类", "凝聚型层次聚类策略：将每个基因作为一个初始簇，成对计算基因间距离，合并距离最小的两个簇，重复"], "check": {"q": "关于K-means聚类过程与层次聚类，下列哪项正确？", "o": ["A. K-means将基因划分为K个簇，使簇内基因表达模式相似", "B. 层次聚类常用分裂型层次聚类", "C. 凝聚型层次聚类先将所有基因作为一个簇", "D. K-means无需初始化质心"], "a": "A", "e": "K-means将基因划分为K个簇，使簇内基因表达模式相似；层次聚类按方向分为聚集型和分裂型，常用凝聚型层次聚类；凝聚型层次聚类将每个基因作为一个初始簇，逐步合并。"}, "cards": [{"front": "K-means聚类和层次聚类的主要区别是什么？", "back": "K-means将基因划分为K个簇，使簇内基因表达模式相似，需预先指定K；层次聚类按方向分为聚集型和分裂型，常用凝聚型，将每个基因作为初始簇，成对计算距离，合并最小距离簇，重复。", "mnemonic": "K-means需指定K，层次聚类不需。", "useImg": false}]}, {"i": 14, "sec": "第四节 功能分析", "title": "SOM聚类应用与富集分析引入", "notes": "本页继续介绍SOM聚类及其应用。图6-10通过SOM聚类揭示了细胞类型GM12878和K562特异性的反式作用因子结合模式，并对不同区域的作用元件进行GO富集以探究潜在功能。图中显示REST和ZNF143介导的神经元抑制、肿瘤坏死因子受体结合、凋亡执行阶段、蛋白质翻译、翻译起始、抗原加工提呈调控等功能模块，以及CTCF、RAD21、SMC3、ZNF143等因子的结合模式。常用聚类分析可用R语言实现。聚类分析将基因划分为不同基因集合，同一集合中的基因在表达模式或功能上很可能具有联系，对这些基因集合进行分析往往比单基因分析更可靠。随后引入富集分析：富集分析利用已知的基因功能注释信息作为先验知识，对目标基因集进行功能富集。富集分析相较于单基因分析具有许多优势：基因集结合功能注释，可降低维度，提高生物学解释的可靠性，并发现协同变化的基因功能模块。", "page": 116, "level": "理解", "img": "assets/img/ch06/p116.jpg", "anim": null, "fig": "图6-10通过SOM聚类展示细胞类型特异性反式作用因子结合模式，观察不同区域作用元件的GO富集结果。", "points": ["SOM聚类揭示细胞类型GM12878和K562特异性的反式作用因子结合模式", "对不同区域的作用元件进行GO富集以探究潜在功能", "图中显示REST和ZNF143介导的神经元抑制、肿瘤坏死因子受体结合、凋亡执行阶段等功能模块", "CTCF、RAD21、SMC3、ZNF143等因子"], "check": {"q": "关于SOM聚类应用与富集分析引入，下列哪项正确？", "o": ["A. SOM聚类不能揭示细胞类型特异性反式作用因子结合模式", "B. 图6-10通过SOM聚类揭示了GM12878和K562特异性的反式作用因子结合模式", "C. 聚类分析不能将基因划分为不同基因集合", "D. 富集分析不能探究潜在功能"], "a": "B", "e": "图6-10通过SOM聚类揭示了细胞类型GM12878和K562特异性的反式作用因子结合模式，并对不同区域的作用元件进行GO富集以探究潜在功能；聚类分析将基因划分为不同基因集合。"}, "cards": [{"front": "SOM聚类在转录组分析中有何应用？", "back": "揭示细胞类型特异性的反式作用因子结合模式，并对不同区域的作用元件进行GO富集以探究潜在功能。", "mnemonic": "SOM聚类揭示结合模式，GO富集探功能。", "useImg": false}]}, {"i": 15, "sec": "第四节 功能分析", "title": "GSEA原理与Fisher精确检验", "notes": "本页介绍基因集富集分析GSEA和Fisher精确检验。GSEA首先根据基因表达量与样本表型的相关性对基因排序，确定基因在基因集中的排序位置。若基因集S中的基因在排序列表L中集中于顶部或底部，则富集分数ES增加或减少，增减幅度取决于基因表达量与表型相关性大小。通过随机分配样本标签、打乱样本顺序，计算ES并重复，得到ES的理论分布ESnull，以此估计观测值ES(S)的显著性P值。结果显著说明功能基因集S中的基因在基因列表L中集中分布于顶部，即基因集显著富集于S所属的特定功能条目。图6-11展示GSEA原理：(a)根据表达量和表型相关性排序，确定单个基因在基因集中的排序位置；(b)对排好序的基因集计算富集得分，确定最大富集得分数值和排序优先的基因子集。后续改良方法有PAGE、GSA等，通过修改富集分数计算方式改进GSEA。注意GSEA主要为芯片数据开发，应用于RNA-seq时需对表达量标准化。Fisher精确检验使用超几何分布，原理是：获取物种全部基因作为背景，共N个基因，其中M个与某功能密切相关；选定差异表达基因或聚类模块基因，假设共n个，其中k个属于该功能，通过超几何分布计算富集显著性。", "page": 117, "level": "掌握", "img": "assets/img/ch06/p117.jpg", "anim": null, "fig": null, "points": ["GSEA首先根据基因表达量与样本表型的相关性对基因排序，确定基因在基因集中的排序位置", "若基因集S中的基因在排序列表L中集中于顶部或底部，则富集分数ES增加或减少", "通过随机分配样本标签、打乱样本顺序，计算ES并重复，得到ES的理论分布ESnull", "Fisher精确检验用于富集分析"], "check": {"q": "关于GSEA原理与Fisher精确检验，下列哪项正确？", "o": ["A. GSEA首先根据基因表达量与样本表型的相关性对基因排序", "B. 若基因集S中的基因在排序列表L中随机分布，则富集分数ES显著增加", "C. GSEA通过随机分配样本标签计算ES，得到ES的理论分布ESnull", "D. 结果显著说明功能基因集S中的基因在基因列表L中随机分布"], "a": "A", "e": "GSEA首先根据基因表达量与样本表型的相关性对基因排序；若基因集S中的基因在排序列表L中集中于顶部或底部，则富集分数ES增加或减少；通过随机分配样本标签计算ES并重复，得到ESnull，估计观测值ES(S)的显著性P值；结果显著说明功能基因集S中的基因在基因列表L中集中分布于顶部或底部。"}, "cards": [{"front": "GSEA的基本原理是什么？", "back": "根据基因表达量与样本表型的相关性对基因排序，确定基因在基因集中的排序位置；若基因集S中的基因在排序列表L中集中于顶部或底部，则富集分数ES增加或减少；通过随机分配样本标签、打乱样本顺序，计算ES并重复，得到ES的理论分布ESnull，以此估计观测值ES。", "mnemonic": "排序→富集分数→随机打乱→理论分布。", "useImg": false}]}, {"i": 16, "sec": "第四节 功能分析", "title": "富集分析工具与共表达网络及WGCNA原理", "notes": "本页介绍富集分析常用工具和共表达网络。富集分析工具除GSEA外，还有DAVID、IPA、clusterProfiler等。富集分析可研究不同基因集蕴含的生物学功能，将RNA-seq产生的大量基因缩小到关键功能和通路，选取重要功能基因进行后续分析和实验验证。共表达网络为研究基因间相互作用和调控关系提供思路。共表达利用功能相关基因在特定环境下协调表达的特点，即表达模式相似的基因可能具有相似功能。一般通过计算基因间相关系数矩阵，设定阈值筛选相关性，以网络形式展现，点代表基因，边代表相关性。相关系数可用皮尔逊相关系数、斯皮尔曼相关系数、偏相关系数等，也可用基于网络拓扑重叠结构的方法如TOM。除相关系数外，也可用距离衡量相似程度。WGCNA是一种基于相关性系数构建共表达网络的方法。其工作原理包括：①样本相关性聚类，根据表达量和表型数据对所有样本聚类，检查异常样本；②计算基因两两之间的相关性，图6-12(b)展示不同幂次β下网络拓扑结构变化情况，需要选择合适的软阈值使网络符合无标度拓扑。", "page": 118, "level": "掌握", "img": "assets/img/ch06/p118.jpg", "anim": null, "fig": null, "points": ["富集分析工具除GSEA外，还有DAVID、IPA、clusterProfiler等", "富集分析可研究不同基因集蕴含的生物学功能，将大量基因缩小到关键功能和通路", "共表达网络为研究基因间相互作用和调控关系提供思路", "共表达利用功能相关基因在特定环境下协调表达的特点"], "check": {"q": "关于富集分析工具与共表达网络及WGCNA原理，下列哪项正确？", "o": ["A. 富集分析工具只有GSEA", "B. DAVID、IPA、clusterProfiler也是常用富集分析工具", "C. 共表达网络不能研究基因间相互作用", "D. 表达模式相似的基因一定具有相同功能"], "a": "B", "e": "富集分析工具除GSEA外，还有DAVID、IPA、clusterProfiler等；共表达网络为研究基因间相互作用和调控关系提供思路；表达模式相似的基因可能具有相似功能，而非一定。"}, "cards": [{"front": "常用富集分析工具有哪些？共表达网络的基本原理是什么？", "back": "富集分析工具：GSEA、DAVID、IPA、clusterProfiler等；共表达网络利用功能相关基因在特定环境下协调表达的特点。", "mnemonic": "GSEA、DAVID、IPA、clusterProfiler；共表达协调表达。", "useImg": false}]}, {"i": 17, "sec": "第四节 功能分析", "title": "WGCNA样本聚类、软阈值选择与模块划分", "notes": "本页展示WGCNA分析的关键图示。图6-12(a)为样本层次聚类树和表型热图，用于检查异常样本，图中样本按表达谱聚类，下方热图显示各样本的表型如t01、t04、t08、t12、t24、t36、t60、ABA等，可观察样本与表型的对应关系，识别离群样本。图6-12(b)左图为尺度独立性（scale independence）随软阈值幂次的变化，右图为平均连通性（mean connectivity）随软阈值幂次的变化。WGCNA需要选择使网络近似无标度拓扑的软阈值β，通常选取尺度独立性达到0.8或0.9以上的最小幂次，同时兼顾平均连通性。图6-12(c)为基因聚类树状图，通过动态树切割（dynamic tree cut）将基因划分为不同模块，不同颜色代表不同模块。WGCNA通过构建加权共表达网络，识别协同表达的基因模块，并将模块与样本表型关联，从而挖掘关键模块和核心基因。该页为整页图，读图时需结合WGCNA步骤：样本聚类检查异常、软阈值选择、模块划分与表型关联。", "page": 119, "level": "理解", "img": "assets/img/ch06/p119.jpg", "anim": null, "fig": "图6-12(a)观察样本按表达谱聚类及表型热图，识别离群样本；图6-12(b)左图选择使尺度独立性达到0.9的软阈值，右图观察平均连通性变化。", "points": ["图6-12(a)为样本层次聚类树和表型热图，用于检查异常样本", "图6-12(b)左图为尺度独立性随软阈值幂次的变化，右图为平均连通性", "WGCNA分析关键步骤：样本聚类、软阈值选择、模块划分"], "check": {"q": "关于WGCNA样本聚类、软阈值选择与模块划分，下列哪项正确？", "o": ["A. 图6-12(a)为样本层次聚类树和表型热图，用于检查异常样本", "B. WGCNA不需要选择软阈值", "C. 尺度独立性随软阈值幂次变化与网络构建无关", "D. 平均连通性不随软阈值幂次变化"], "a": "A", "e": "图6-12(a)为样本层次聚类树和表型热图，用于检查异常样本；WGCNA需要选择使网络满足无标度拓扑的软阈值；图6-12(b)展示尺度独立性和平均连通性随软阈值幂次的变化。"}, "cards": [{"front": "WGCNA分析中软阈值选择的原则是什么？", "back": "选择使尺度独立性达到0.9的软阈值幂次，同时观察平均连通性变化。", "mnemonic": "尺度独立性0.9选软阈值。", "useImg": false}]}, {"i": 18, "sec": "第四节 功能分析", "title": "WGCNA模块特征基因聚类与模块-性状关系可视化", "notes": "本页为整页图，展示加权基因共表达网络分析（WGCNA）中两个关键可视化结果。上图是模块特征基因（module eigengene, ME）的聚类树：每个模块用其第一主成分（ME）代表整体表达模式，对ME进行层次聚类可判断模块间表达相似性，距离越近的模块表达模式越相似，可据此合并高度相似的模块。下图是模块-性状关系热图（module-trait relationships）：行是各颜色模块（MEblue、MEbrown、MEturquoise等），列是样本性状或临床表型，单元格数值为模块特征基因与性状的相关系数，颜色深浅表示相关强度（红正蓝负），括号内为显著性P值。读图时先看聚类树判断模块相似性，再在热图中寻找与目标性状显著相关的模块，从而锁定关键模块并进一步挖掘其中的核心基因。该页属于第四节功能分析中‘网络模块挖掘’的图示部分。", "page": 120, "level": "理解", "img": "assets/img/ch06/p120.jpg", "anim": null, "fig": "上图观察ME聚类树，判断模块间相似性；下图观察模块-性状关系热图，颜色深浅表示相关性大小，寻找与特定表型显著相关的模块。", "points": ["模块特征基因(ME)的聚类树：每个模块用其第一主成分(ME)代表整体表达模式", "对ME进行层次聚类可判断模块间表达相似性，距离越近的模块表达模式越相似", "模块-性状关系热图展示模块与表型的相关性"], "check": {"q": "关于WGCNA模块特征基因聚类与模块-性状关系可视化，下列哪项正确？", "o": ["A. 模块特征基因ME是模块的第一主成分", "B. 对ME进行层次聚类不能判断模块间表达相似性", "C. 模块-性状关系热图中行是性状，列是模块", "D. 距离越远的模块表达模式越相似"], "a": "A", "e": "模块特征基因ME是模块的第一主成分，代表整体表达模式；对ME进行层次聚类可判断模块间表达相似性，距离越近的模块表达模式越相似；模块-性状关系热图中行是各颜色模块，列是性状。"}, "cards": [{"front": "模块特征基因(ME)聚类树和模块-性状关系热图的作用是什么？", "back": "ME聚类树：判断模块间表达相似性，距离越近的模块表达模式越相似，可据此合并高度相似的模块；模块-性状关系热图：展示模块与表型的相关性。", "mnemonic": "ME聚类看相似，热图看相关性。", "useImg": false}]}, {"i": 19, "sec": "第四节 功能分析", "title": "网络模块挖掘方法与可变剪切分析", "notes": "本页包含两部分。第一部分‘网络模块挖掘’：介绍共表达网络的图论拓扑属性，包括节点、度、度分布、聚集系数、直径、平均路径长度等；基因互作网络符合无标度分布，即多数基因只与少数基因相连，极少数基因与大量基因相连，这些高度连接的基因称为hub基因（核心基因）。WGCNA可按连通性排序找核心基因，也可根据已知基因找TOM值较大且连通性高的基因。其他模块挖掘算法有MCODE（基于图论）、MCL（模拟随机流的无监督聚类）、Qcut（无参数基于划分）。需注意共表达网络基于相关系数，只能说明相关性而非因果性，构建调控网络需结合其他手段。第二部分‘可变剪切’：前体RNA经可变剪切等转录后修饰形成成熟mRNA，导致基因水平与转录本水平表达不一致，同一基因可产生不同转录本异构体，其表达与差异分析是难点。早期BASIS用分层贝叶斯模型同时估算异构体表达并检测差异；CuffDiff2先计算所有异构体表达再分析差异；其他工具还有FDM、rSeqD等。", "page": 121, "level": "掌握", "img": "assets/img/ch06/p121.jpg", "anim": null, "fig": null, "points": ["共表达网络的图论拓扑属性：节点、度、度分布、聚集系数、直径、平均路径长度等", "基因互作网络符合无标度分布，即多数基因只与少数基因相连，极少数基因与大量基因相连", "高度连接的基因称为hub基因(核心基因)", "WGCNA可按连通性排序找核心基因，也可根据已知基因找TOM值较大且连通性高的基因", "其他模块挖掘算法有MCL等"], "check": {"q": "关于网络模块挖掘方法与可变剪切分析，下列哪项正确？", "o": ["A. 基因互作网络符合随机网络分布", "B. hub基因是与少数基因相连的基因", "C. 基因互作网络符合无标度分布，hub基因与大量基因相连", "D. WGCNA不能按连通性排序找核心基因"], "a": "C", "e": "基因互作网络符合无标度分布，即多数基因只与少数基因相连，极少数基因与大量基因相连，这些高度连接的基因称为hub基因；WGCNA可按连通性排序找核心基因。"}, "cards": [{"front": "什么是hub基因？如何寻找？", "back": "hub基因是共表达网络中高度连接的基因，与大量基因相连；WGCNA可按连通性排序找核心基因，也可根据已知基因找TOM值较大且连通性高的基因。", "mnemonic": "hub基因高连接，按连通性排序找。", "useImg": false}]}, {"i": 20, "sec": "第四节 功能分析", "title": "多组学整合分析与RNA-seq案例系统配置及数据获取", "notes": "本页先讲转录组学拓展分析中的多组学整合：结合全基因组测序可探测SNP和eQTL研究基因型与表达谱关系；结合DNA表观修饰数据探究表观修饰对差异表达基因的影响；结合ChIP-seq研究转录因子调控动态并构建转录调控网络；结合ncRNA数据构建mRNA-ncRNA共表达网络探究ncRNA功能；结合蛋白质组和代谢组数据时，RNA-seq与蛋白质组相关性较低需慎重，而与代谢组结合可从基因表达和代谢物两个水平构建代谢网络。多类型数据整合是转录组学研究趋势。随后进入第五节RNA-seq数据分析案例，介绍系统配置和数据预处理：案例数据和软件可在线下载，提供命令脚本和操作视频（http://www.cls.zju.edu.cn/binfo/textbook/video/RNA-seq/）。系统配置采用Linux和Windows 7，官网下载VMware Workstation 12和Ubuntu-16.04镜像，虚拟机配置64位、内存4GB、硬盘160GB；Windows 7配置64位、内存16GB、硬盘1TB。数据来自NCBI GEO，检索号GS开头（后续页给出具体SRR号）。", "page": 122, "level": "了解", "img": "assets/img/ch06/p122.jpg", "anim": null, "fig": null, "points": ["多组学整合：结合全基因组测序可探测SNP和eQTL研究基因型与表达谱关系", "结合DNA表观修饰数据探究表观修饰对差异表达基因的影响", "结合ChIP-seq研究转录因子调控动态并构建转录调控网络", "结合ncRNA数据构建mRNA-ncRNA共表达网络探究ncRNA功能", "结合蛋白质组和代谢组数据时，RNA-seq与蛋白质组相关性较低需慎重"], "check": {"q": "关于多组学整合分析与RNA-seq案例系统配置及数据获取，下列哪项正确？", "o": ["A. 结合全基因组测序可探测SNP和eQTL", "B. RNA-seq与蛋白质组相关性很高，可直接整合", "C. 结合ChIP-seq不能研究转录因子调控动态", "D. 多类型数据整合不是转录组学拓展分析方向"], "a": "A", "e": "结合全基因组测序可探测SNP和eQTL研究基因型与表达谱关系；RNA-seq与蛋白质组相关性较低，整合需慎重；结合ChIP-seq可研究转录因子调控动态并构建转录调控网络；多类型数据整合是转录组学拓展分析方向。"}, "cards": [{"front": "多组学整合分析有哪些常见组合？", "back": "结合全基因组测序探测SNP和eQTL；结合DNA表观修饰数据；结合ChIP-seq研究转录因子调控；结合ncRNA数据构建mRNA-ncRNA共表达网络；结合蛋白质组和代谢组数据。", "mnemonic": "基因组、表观、ChIP、ncRNA、蛋白代谢。", "useImg": false}]}, {"i": 21, "sec": "第四节 功能分析", "title": "RNA-seq数据下载、质量评估与质量控制", "notes": "本页为RNA-seq案例的数据预处理步骤。1.数据下载：用fastq-dump下载SRA文件，如fastq-dump SRR3418005.sra，对其余3个文件执行同样命令，共产生4个原始测序数据文件约32.4GB。2.质量评估：用FastQC检测原始数据质量，命令fastqc -o ../fastqc_results -f fastq SRR3418005.fastq等，-o指定输出目录。以SRR3418005为例，FastQC结果（图6-13）显示Per base sequence quality正常，但Per base sequence content显示前约12位碱基核酸比例失常。若对质量要求高，可用FastX_Toolkit进行质量控制。3.质量控制：用fastx_trimmer截去reads前12位碱基，命令fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq，参数-Q为Illumina编码转换，-f为截取起始位置，-i输入，-o输出。再用fastq_quality_filter过滤低质量reads，命令fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq，-q 20表示质量值阈值，-p 80表示保留至少80%碱基达到该质量的reads。", "page": 123, "level": "掌握", "img": "assets/img/ch06/p123.jpg", "anim": null, "fig": null, "points": ["数据下载：用fastq-dump下载SRA文件，如fastq-dump SRR3418005.sra", "共产生4个原始测序数据文件约32.4GB", "质量评估：用FastQC检测原始数据质量，命令fastqc -o ../fastqc_results -f fastq SRR341800"], "check": {"q": "关于RNA-seq数据下载、质量评估与质量控制，下列哪项正确？", "o": ["A. fastq-dump用于下载SRA文件", "B. FastQC命令中-o指定输出目录", "C. 案例共产生4个原始测序数据文件约32.4GB", "D. 以上都正确"], "a": "D", "e": "用fastq-dump下载SRA文件；FastQC命令中-o指定输出目录；案例共产生4个原始测序数据文件约32.4GB。"}, "cards": [{"front": "RNA-seq案例中数据下载和质量评估使用什么工具？", "back": "数据下载：fastq-dump；质量评估：FastQC。", "mnemonic": "fastq-dump下载，FastQC评估。", "useImg": false}]}, {"i": 22, "sec": "第四节 功能分析", "title": "HISAT2比对与SAM文件处理", "notes": "本页介绍RNA-seq案例的比对和拼接中的比对步骤。采用有参基因组策略，用HISAT2将reads比对到基因组。1.建立基因组索引：先提取可变剪切和外显子信息，命令hisat2_extract_splice_sites.py tair10.gtf > tair10.ss和hisat2_extract_exons.py tair10.gtf > tair10.exon，再建索引hisat2-build --ss ../gff/tair10.ss --exon ../gff/tair10.exon ../genome/fasta/tair10.fasta tair10。注意使用--ss和--exon会消耗大量内存（拟南芥基因组索引可能需12G以上内存），故本案例实际未添加这两个参数，tair10为索引文件前缀。人和小鼠索引库可在HISAT2官网下载。2.reads比对：用HISAT2比对，命令hisat2 -p 2 --dta -x ../data/index/tair10 -U ../data/fastx_results/SRR3418005_filtered.fastq -S SRR3418005.sam，处理4个样本约10min。参数-p为线程数，--dta用于转录本拼接，-x为index库前缀，-U为单端测序文件（双端用-1和-2），-S为输出SAM文件。3.SAM文件处理：用samtools对SAM排序并转换为BAM，命令samtools sort -@2 -m 200M -o SRR3418005.bam SRR3418005.sam，总共耗时约45min。", "page": 124, "level": "掌握", "img": "assets/img/ch06/p124.jpg", "anim": null, "fig": null, "points": ["采用有参基因组策略，用HISAT2将reads比对到基因组", "建立基因组索引：先提取可变剪切和外显子信息，命令hisat2_extract_splice_sites.py tair10.gtf > tair10.ss和hisat2_extract_exons.py tair10.gtf > tair10.ex", "然后使用hisat2-build构建索引", "比对后得到SAM文件，需转换为BAM并排序"], "check": {"q": "关于HISAT2比对与SAM文件处理，下列哪项正确？", "o": ["A. 采用无参基因组策略", "B. 先用hisat2_extract_splice_sites.py和hisat2_extract_exons.py提取可变剪切和外显子信息", "C. HISAT2不能将reads比对到基因组", "D. 建立索引不需要参考基因组注释"], "a": "B", "e": "案例采用有参基因组策略，用HISAT2将reads比对到基因组；先提取可变剪切和外显子信息，再建索引；HISAT2可将reads比对到基因组。"}, "cards": [{"front": "RNA-seq案例中比对使用什么工具？如何建立基因组索引？", "back": "使用HISAT2将reads比对到基因组；建立索引：先提取可变剪切和外显子信息，命令hisat2_extract_splice_sites.py tair10.gtf > tair10.ss和hisat2_extract_exons.py tair10.gtf > tair10.ex，然后使用hisat2-build构建索引。", "mnemonic": "HISAT2比对，先提取再建索引。", "useImg": false}]}, {"i": 23, "sec": "第四节 功能分析", "title": "IGV可视化比对结果与覆盖度分析", "notes": "本页为整页图，展示RNA-seq比对结果的可视化。图6-14为IGV（Integrative Genomics Viewer）比对结果可视化，上方是基因组坐标轴（约9.300 kb至9.310 kb），下方显示SRR3418005.bam的reads比对情况，灰色横条代表比对到参考基因组的reads，可直观查看外显子-内含子边界、剪切位点和覆盖深度。下方还有两张覆盖度图：Coverage across reference显示SRR3418005.bam在参考序列上的覆盖度分布，横轴为位置（bp），纵轴为覆盖深度；Coverage Profile Along Genes (Total)显示SRR3418005.bam沿基因的覆盖度轮廓，横轴为基因位置，纵轴为覆盖度（约0至26,000）。读图时注意：IGV中reads堆积高度反映表达丰度，剪切位点表现为reads跨越外显子连接；覆盖度曲线可评估测序均一性和基因表达水平，若覆盖度在基因5'或3'端偏好则提示降解或建库偏差。该页属于第五节RNA-seq数据分析案例中比对结果的可视化验证环节。", "page": 125, "level": "理解", "img": "assets/img/ch06/p125.jpg", "anim": null, "fig": "图6-14为IGV比对结果可视化，观察reads在外显子-内含子边界的分布，判断剪切位点和覆盖深度。", "points": ["IGV可视化比对结果，上方是基因组坐标轴，下方显示reads比对情况", "灰色横条代表比对到参考基因组的reads，可直观查看外显子-内含子边界、剪切位点和覆盖深度", "下方还有覆盖度分析"], "check": {"q": "关于IGV可视化比对结果与覆盖度分析，下列哪项正确？", "o": ["A. IGV不能可视化BAM文件", "B. 图6-14中灰色横条代表比对到参考基因组的reads", "C. 覆盖度图不能显示覆盖深度", "D. IGV不能查看外显子-内含子边界"], "a": "B", "e": "图6-14为IGV比对结果可视化，灰色横条代表比对到参考基因组的reads，可直观查看外显子-内含子边界、剪切位点和覆盖深度；下方还有覆盖度图。"}, "cards": [{"front": "IGV可视化比对结果可以观察什么？", "back": "可直观查看外显子-内含子边界、剪切位点和覆盖深度。", "mnemonic": "IGV看边界、剪切位点、覆盖深度。", "useImg": false}]}, {"i": 24, "sec": "第五节 RNA-seq数据分析案例", "title": "StringTie转录本合并、GffCompare注释比较与FPKM表达丰度计算", "notes": "本页介绍RNA-seq数据分析案例中转录本组装后的合并、注释比较和表达丰度计算。首先，使用StringTie的--merge模式将多个样本的转录本注释整合为统一非冗余转录本集合，命令中-p指定线程数，-G提供参考基因组注释，-o输出合并后的GTF文件，目的是便于新转录本鉴别和后续定量。其次，使用GffCompare将合并转录本与参考注释比较，-r指定参考注释，-o指定输出文件前缀，可识别已知及潜在新转录本；注意参考GTF中Gene ID不能重复，否则报错。最后，计算表达丰度：用StringTie -e只评估已知转录本丰度，-G提供注释文件，-A输出基因水平FPKM，-o输出转录本水平GTF，输入为比对BAM文件。每个BAM经计算输出基因和转录本两个GTF，包含FPKM值；单端测序中FPKM与RPKM等价。后续可提取各样本FPKM组成表达矩阵，用于差异分析。", "page": 126, "level": "掌握", "img": "assets/img/ch06/p126.jpg", "anim": null, "fig": null, "points": ["StringTie的--merge模式将多个样本的转录本注释整合为统一非冗余转录本集合", "命令中-p指定线程数，-G提供参考基因组注释，-o输出合并后的GTF文件", "GffCompare将合并转录本与参考注释比较，-r指定参考注释", "FPKM表达丰度计算"], "check": {"q": "关于StringTie转录本合并、GffCompare注释比较与FPKM表达丰度计算，下列哪项正确？", "o": ["A. StringTie的--merge模式用于将多个样本的转录本注释整合为统一非冗余转录本集合", "B. GffCompare不能识别潜在新转录本", "C. 参考GTF中Gene ID可直接用于clusterProfiler富集", "D. FPKM不能用于表达丰度计算"], "a": "A", "e": "StringTie的--merge模式将多个样本的转录本注释整合为统一非冗余转录本集合；GffCompare可识别已知及潜在新转录本；参考GTF中Gene ID需转换后才能用于clusterProfiler富集；FPKM可用于表达丰度计算。"}, "cards": [{"front": "StringTie的--merge模式和GffCompare的作用是什么？", "back": "StringTie的--merge模式将多个样本的转录本注释整合为统一非冗余转录本集合，便于新转录本鉴别和后续定量；GffCompare将合并转录本与参考注释比较。", "mnemonic": "StringTie合并，GffCompare比较。", "useImg": false}]}, {"i": 25, "sec": "第五节 RNA-seq数据分析案例", "title": "差异表达火山图、样本聚类热图与GO富集分析", "notes": "本页展示差异表达分析和功能富集。图6-16为差异表达火山图，横轴为log2 FoldChange，纵轴为-log10显著性，用于直观显示显著上调/下调基因；图6-17为样本表达模式聚类热图，可观察样本间相似性和基因表达模式。随后进行富集分析：对差异显著基因做GO和KEGG富集，案例使用clusterProfiler，也可用DAVID。GO富集需在R中安装org.At.tair.db拟南芥注释库；由于clusterProfiler不识别TAIR ID，需先将基因ID转换为NCBI ENTREZ GENE ID，可用DAVID在线转换。核心命令enrichGO(gene_id, org.At.tair.db, ont=\"BP\")进行生物学过程富集。结果可导出CSV，并用WEGO、AgriGO或REVIGO可视化；REVIGO可去除冗余GO条目并构建GO相关性网络，下载xgmml文件后导入Cytoscape进一步分析。", "page": 127, "level": "掌握", "img": "assets/img/ch06/p127.jpg", "anim": null, "fig": "图6-16火山图观察显著上调和下调基因；图6-17热图观察样本聚类和基因表达模式。", "points": ["差异表达火山图：横轴为log2 FoldChange，纵轴为-log10显著性，用于直观显示显著上调/下调基因", "样本表达模式聚类热图：可观察样本间相似性和基因表达模式", "富集分析：对差异显著基因做GO和KEGG富集，案例使用clusterProfiler，也可用DAVID", "GO富集需在R中安装org"], "check": {"q": "关于差异表达火山图、样本聚类热图与GO富集分析，下列哪项正确？", "o": ["A. 火山图横轴为log2 FoldChange，纵轴为-log10显著性", "B. 样本表达模式聚类热图不能观察样本间相似性", "C. GO富集不需要物种注释库", "D. clusterProfiler可直接识别所有GTF中的Gene ID"], "a": "A", "e": "图6-16为差异表达火山图，横轴为log2 FoldChange，纵轴为-log10显著性；图6-17为样本表达模式聚类热图，可观察样本间相似性和基因表达模式；GO富集需安装物种注释库；clusterProfiler不识别某些GTF中的Gene ID，需转换。"}, "cards": [{"front": "差异表达火山图和样本聚类热图分别展示什么？", "back": "火山图：横轴log2 FoldChange，纵轴-log10显著性，直观显示显著上调/下调基因；热图：观察样本间相似性和基因表达模式。", "mnemonic": "火山图看差异，热图看聚类。", "useImg": false}]}, {"i": 26, "sec": "第五节 RNA-seq数据分析案例", "title": "KEGG通路富集与WGCNA共表达网络构建", "notes": "本页继续富集分析并引入共表达网络。KEGG富集使用clusterProfiler的enrichKEGG函数，指定organism=\"ath\"、keyType=\"ncbi-geneid\"，对差异基因进行通路富集。表6-5列出显著通路，如角质、木栓质和蜡质生物合成、MAPK信号通路-植物、苯丙素生物合成等，包含GeneRatio、BgRatio和p.adjust等统计量，用于判断通路显著性。随后介绍共表达网络构建：使用WGCNA，从GEO下载28个样本的基因表达数据，提取差异显著基因在所有样本中的FPKM值，按WGCNA流程计算加权相关性矩阵和TOM连通性。参数中软阈值power选取56，连通性阈值选取0.35，最终网络包含130个基因，节点半径越大代表总连通性越高。富集分析发现网络基因主要富集于脱落酸响应（GO:0009737）等生物学过程，说明共表达模块与特定功能相关。", "page": 128, "level": "理解", "img": "assets/img/ch06/p128.jpg", "anim": null, "fig": "表6-5列出KEGG富集显著通路，查看GeneRatio、BgRatio和p.adjust，判断通路显著性。", "points": ["KEGG富集使用clusterProfiler的enrichKEGG函数，指定organism=\"ath\"、keyType=\"ncbi-geneid\"", "表6-5列出显著通路，如角质、木栓质和蜡质生物合成、MAPK信号通路-植物、苯丙素生物合成等", "包含GeneRatio、BgRatio和p.adjust等指标", "WGCNA共表达网络构建"], "check": {"q": "关于KEGG通路富集与WGCNA共表达网络构建，下列哪项正确？", "o": ["A. KEGG富集使用clusterProfiler的enrichKEGG函数，指定organism=\"ath\"、keyType=\"ncbi-geneid\"", "B. 表6-5中不包含p.adjust统计量", "C. WGCNA不能从GEO下载数据构建共表达网络", "D. KEGG富集不能判断通路显著性"], "a": "A", "e": "KEGG富集使用clusterProfiler的enrichKEGG函数，指定organism=\"ath\"、keyType=\"ncbi-geneid\"；表6-5包含GeneRatio、BgRatio和p.adjust等统计量，用于判断通路显著性；WGCNA可从GEO下载数据构建共表达网络。"}, "cards": [{"front": "KEGG富集使用什么函数？案例中显著通路有哪些？", "back": "使用clusterProfiler的enrichKEGG函数，指定organism=\"ath\"、keyType=\"ncbi-geneid\"；显著通路如角质、木栓质和蜡质生物合成、MAPK信号通路-植物、苯丙素生物合成等。", "mnemonic": "enrichKEGG，ath物种；角质、MAPK、苯丙素。", "useImg": false}]}, {"i": 27, "sec": "第五节 RNA-seq数据分析案例", "title": "脱落酸处理下拟南芥基因调控共表达网络图与思考题", "notes": "本页主体为图6-19，展示脱落酸处理下拟南芥基因调控共表达网络。图中节点代表基因，边代表基因间表达相关性；节点半径越大表示总连通性越高，即该基因在网络中连接更多基因，可能处于调控枢纽位置。网络基于WGCNA构建，包含130个基因，主要富集于脱落酸响应等过程，可用于挖掘关键调控基因和模块。读图时应关注高连通性节点、模块颜色划分及与表型的关联。页末列出思考题，覆盖转录组学定义、RNA-seq与基因芯片比较、转录本测定发展、链特异性文库、RNA-seq文库制备、RPKM与DESeq标准化比较、无参考基因组RNA-seq分析、差异表达为何需要生物学重复、SOM聚类过程以及利用RNA-seq研究基因融合等，用于复习本章核心概念。", "page": 129, "level": "理解", "img": "assets/img/ch06/p129.jpg", "anim": null, "fig": "图6-19共表达网络图，观察节点大小(连通性)和模块颜色，寻找关键调控基因。", "points": ["图6-19展示脱落酸处理下拟南芥基因调控共表达网络", "节点代表基因，边代表基因间表达相关性", "节点半径越大表示总连通性越高，可能处于调控枢纽位置", "网络基于WGCNA构建，包含130个基因，主要富集于脱落酸响应等过程", "读图关注高连通性节点、模块颜色划分及与表型的关联"], "check": {"q": "关于脱落酸处理下拟南芥基因调控共表达网络图与思考题，下列哪项正确？", "o": ["A. 图6-19中节点半径越大表示总连通性越低", "B. 图6-19网络基于WGCNA构建，包含130个基因", "C. 图中边代表基因与表型的关系", "D. 网络主要富集于光合作用过程"], "a": "B", "e": "图6-19展示脱落酸处理下拟南芥基因调控共表达网络，基于WGCNA构建，包含130个基因，主要富集于脱落酸响应等过程；节点代表基因，边代表基因间表达相关性；节点半径越大表示总连通性越高。"}, "cards": [{"front": "图6-19共表达网络图中节点大小和颜色代表什么？", "back": "节点代表基因，边代表基因间表达相关性；节点半径越大表示总连通性越高，可能处于调控枢纽位置；模块颜色划分不同共表达模块。", "mnemonic": "节点大小看连通性，颜色看模块。", "useImg": false}]}, {"i": 28, "sec": "第五节 RNA-seq数据分析案例", "title": "参考文献（一）", "notes": "本页为《生物信息学》第六章转录组学的参考文献起始部分，列出多篇经典方法学文献。内容包括：Aijö等关于RNA-seq时间序列分析的方法；Adams等1991年关于互补DNA测序和人类基因组计划的早期工作；Anders和Huber提出DESeq差异表达分析；Anders等发布HTSeq高通量测序数据计数框架；Andrews的FastQC质控工具；Bader和Hogue的蛋白质互作网络复合物发现方法；Baruzzo等对RNA-seq比对器的综合基准测试；Bolger等开发的Trimmomatic读段修剪工具。这些文献对应RNA-seq分析中的质控、比对、计数、差异表达和时间序列分析等关键步骤，可作为深入学习的参考。", "page": 130, "level": "了解", "img": "assets/img/ch06/p130.jpg", "anim": null, "fig": null, "points": ["参考文献起始部分，列出多篇经典方法学文献", "包括Aijö等关于RNA-seq时间序列分析的方法", "Adams等1991年关于互补DNA测序和人类基因组计划的早期工作", "Anders和Huber提出DESeq差异表达分析", "Anders等发布HTSeq高通量测序数据计数框架"], "check": {"q": "关于参考文献（一）中列出的方法学文献，下列哪项正确？", "o": ["A. Anders和Huber提出DESeq差异表达分析", "B. Andrews开发了HISAT", "C. Langfelder和Horvath开发了FastQC", "D. Kim等开发了WGCNA"], "a": "A", "e": "Anders和Huber提出DESeq差异表达分析；Andrews开发FastQC；Langfelder和Horvath提出WGCNA；Kim等开发HISAT。"}, "cards": [{"front": "DESeq和HTSeq分别由谁提出？", "back": "DESeq由Anders和Huber提出；HTSeq由Anders等发布。", "mnemonic": "Anders和Huber提出DESeq，Anders等发布HTSeq。", "useImg": false}]}, {"i": 29, "sec": "第五节 RNA-seq数据分析案例", "title": "参考文献（二）", "notes": "本页续列转录组学相关参考文献，涵盖比对、网络分析和通路分析工具。包括：Kim等2015年开发的HISAT快速剪接比对器，低内存需求；Kim等2013年TopHat2，可处理插入、缺失和基因融合的转录组比对；Kramer等关于Ingenuity Pathway Analysis的因果分析方法；Langfelder和Horvath提出的WGCNA加权相关网络分析R包；Langmead和Salzberg开发的Bowtie 2快速间隙比对工具；Leng等关于RNA-seq差异表达分析的方法。这些文献对应RNA-seq数据分析中的比对、网络构建和功能解释等环节，有助于理解本章案例所用工具的原理和适用场景。", "page": 131, "level": "了解", "img": "assets/img/ch06/p131.jpg", "anim": null, "fig": null, "points": ["续列转录组学相关参考文献，涵盖比对、网络分析和通路分析工具", "Kim等2015年开发的HISAT快速剪接比对器，低内存需求", "Kim等2013年TopHat2，可处理插入、缺失和基因融合的转录组比对", "Kramer等关于Ingenuity Pathway Analysis的因果分析方法", "Langfelder和Horvath提出的WGCNA加权相关网络分析"], "check": {"q": "关于参考文献（二）中列出的工具，下列哪项正确？", "o": ["A. HISAT是Kim等2015年开发的快速剪接比对器，低内存需求", "B. TopHat2不能处理插入、缺失和基因融合", "C. WGCNA是Langmead和Salzberg开发的", "D. Bowtie 2是Langfelder和Horvath开发的"], "a": "A", "e": "HISAT是Kim等2015年开发的快速剪接比对器，低内存需求；TopHat2可处理插入、缺失和基因融合；WGCNA由Langfelder和Horvath提出；Bowtie 2由Langmead和Salzberg开发。"}, "cards": [{"front": "HISAT和TopHat2分别由谁开发？WGCNA由谁提出？", "back": "HISAT由Kim等2015年开发；TopHat2由Kim等2013年开发；WGCNA由Langfelder和Horvath提出。", "mnemonic": "Kim开发HISAT和TopHat2，Langfelder和Horvath提出WGCNA。", "useImg": false}]}, {"i": 30, "sec": "第五节 RNA-seq数据分析案例", "title": "RNA-seq差异表达分析工具与网络分析参考文献", "notes": "本页为《生物信息学》第六章转录组学第五节RNA-seq数据分析案例的参考文献页，列出了RNA-seq数据分析中常用的差异表达分析软件和网络分析工具。edgeR是一个基于负二项分布的Bioconductor包，用于数字基因表达数据的差异表达分析，适用于RNA-seq计数数据；DEGseq是另一个R包，专门用于从RNA-seq数据中识别差异表达基因；RSeQC用于RNA-seq实验的质量控制，可评估测序质量、比对质量、链特异性等；Oases用于跨表达水平动态范围的稳健de novo RNA-seq组装；Cytoscape是一个用于生物分子相互作用网络整合建模的软件环境，常用于基因共表达网络或蛋白互作网络的可视化与分析；Shannon等2003年发表的Cytoscape文章是网络分析领域的经典文献。此外，还涉及网络社区发现方法（Ruan & Zhang, 2008）和差异表达软件包比较（Seyednasrollah等, 2013）。这些文献是理解RNA-seq数据分析流程中差异表达和网络分析的重要参考。学习时应了解各工具的主要用途和适用场景，掌握edgeR和DEGseq的基本原理，理解Cytoscape在网络分析中的作用。", "page": 132, "level": "了解", "img": "assets/img/ch06/p132.jpg", "anim": null, "fig": null, "points": ["edgeR是一个基于负二项分布的Bioconductor包，用于数字基因表达数据的差异表达分析", "DEGseq是另一个R包，专门用于从RNA-seq数据中识别差异表达基因", "RSeQC用于RNA-seq实验的质量控制"], "check": {"q": "关于RNA-seq差异表达分析工具与网络分析参考文献，下列哪项正确？", "o": ["A. edgeR是基于负二项分布的Bioconductor包，用于数字基因表达数据的差异表达分析", "B. DEGseq不能从RNA-seq数据中识别差异表达基因", "C. RSeQC不能评估链特异性", "D. Oases不能用于转录本组装"], "a": "A", "e": "edgeR是基于负二项分布的Bioconductor包，用于数字基因表达数据的差异表达分析；DEGseq是R包，专门用于从RNA-seq数据中识别差异表达基因；RSeQC用于RNA-seq实验质量控制，可评估测序质量、比对质量、链特异性等；Oases用于转录本组装。"}, "cards": [{"front": "edgeR、DEGseq、RSeQC分别是什么？", "back": "edgeR：基于负二项分布的Bioconductor包，用于数字基因表达数据的差异表达分析；DEGseq：R包，用于从RNA-seq数据中识别差异表达基因；RSeQC：用于RNA-seq实验的质量控制。", "mnemonic": "edgeR差异表达，DEGseq识别差异，RSeQC质控。", "useImg": false}]}, {"i": 31, "sec": "第五节 RNA-seq数据分析案例", "title": "RNA-seq数据分析案例参考文献（续）", "notes": "本页继续列出第六章转录组学第五节RNA-seq数据分析案例的参考文献，涵盖RNA-seq数据分析的多个关键方面。Wang等2009年发表的DEGseq文章介绍了从RNA-seq数据中识别差异表达基因的R包；Wang等2012年的RSeQC文章提供了RNA-seq实验的质量控制工具；Wang等2009年的Nature Reviews Genetics文章综述了RNA-seq作为转录组学革命性工具的原理和应用；Wu和Nacu 2010年发表的文章介绍了Fast和SNP-tolerant检测复杂变异和剪接的方法；Xie等2013年研究了人类细胞中动态反式作用因子的共定位；Xie等2014年发表了SOAPdenovo-Trans，用于短读长数据的de novo转录组组装。这些文献覆盖了RNA-seq数据分析的完整流程：从质量控制（RSeQC）、比对和变异检测、转录本组装（SOAPdenovo-Trans）、差异表达分析（DEGseq）到功能网络分析。学习时应理解RNA-seq数据分析的主要步骤和常用工具，掌握差异表达分析的基本方法，了解de novo组装在无参考基因组物种中的应用。", "page": 133, "level": "了解", "img": "assets/img/ch06/p133.jpg", "anim": null, "fig": null, "points": ["Wang等2009年发表的DEGseq文章介绍了从RNA-seq数据中识别差异表达基因的R包", "Wang等2012年的RSeQC文章提供了RNA-seq实验的质量控制工具", "Wang等2009年的Nature Reviews Genetics文章综述了RNA-seq"], "check": {"q": "关于RNA-seq数据分析案例参考文献（续），下列哪项正确？", "o": ["A. Wang等2009年发表的DEGseq文章介绍了从RNA-seq数据中识别差异表达基因的R包", "B. Wang等2012年的RSeQC文章提供了基因组组装工具", "C. Wang等2009年的Nature Reviews Genetics文章综述了蛋白质组学", "D. Wu和Nacu 2010年发表的是WGCNA方法"], "a": "A", "e": "Wang等2009年发表的DEGseq文章介绍了从RNA-seq数据中识别差异表达基因的R包；Wang等2012年的RSeQC文章提供了RNA-seq实验的质量控制工具；Wang等2009年的Nature Reviews Genetics文章综述了RNA-seq作为转录组学革命性工具的原理和应用；Wu和Nacu 2010年发表的是Oases相关方法。"}, "cards": [{"front": "Wang等2009年和2012年分别发表了什么文章？", "back": "2009年发表DEGseq文章，介绍从RNA-seq数据中识别差异表达基因的R包；2012年发表RSeQC文章，提供RNA-seq实验的质量控制工具。", "mnemonic": "2009 DEGseq，2012 RSeQC。", "useImg": false}]}], "mcq": [{"id": "ch06_mcq_1", "mod": "第六章 转录组学", "modI": 0, "q": "关于转录组学，以下描述正确的是？", "o": ["A. 转录组学的研究对象是基因组DNA", "B. 转录组学一词最早在20世纪90年代提出", "C. 转录组仅指mRNA", "D. 转录组学从蛋白质水平研究基因表达"], "a": "B", "e": "转录组学一词最早在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。广义上转录组包括mRNA、rRNA、tRNA、ncRNA等，但有时特指mRNA。转录组学从RNA水平研究基因表达。", "kp": "ch06_s0_0"}, {"id": "ch06_mcq_2", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq与基因芯片相比，以下哪项不是RNA-seq的优势？", "o": ["A. 不依赖于参考基因组", "B. 可以直接测定转录本序列和含量", "C. 通量极高", "D. 荧光信号动态检测范围有限"], "a": "D", "e": "荧光信号动态检测范围有限是基因芯片的缺陷，不是RNA-seq的优势。RNA-seq的优势包括不依赖参考基因组、直接测定转录本序列和含量、通量极高、成本日益降低等。", "kp": "ch06_s0_2"}, {"id": "ch06_mcq_3", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq试验设计中，对于有参考基因组且不进行可变剪切或新转录本分析的情况，每个样本最少需要多少有效reads？", "o": ["A. 1M", "B. 5M", "C. 10M", "D. 30M"], "a": "B", "e": "根据ENCODE推荐，有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少只需要5M的有效reads。small RNA一般需要30M以上的有效匹配reads。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_4", "mod": "第六章 转录组学", "modI": 0, "q": "关于链特异性文库，以下描述正确的是？", "o": ["A. 无法区分转录本来源", "B. 保留了转录本的方向信息", "C. 价格比非链特异性文库低", "D. 不利于可变剪切鉴别"], "a": "B", "e": "链特异性文库在建库时保留了转录本的方向信息，用以区分转录本来源，避免互补链干扰。相较于非链特异性文库，基因表达定量和可变剪切鉴别更准确，但价格更高。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_5", "mod": "第六章 转录组学", "modI": 0, "q": "FASTQ文件中，一个read通常由几行组成？", "o": ["A. 2行", "B. 3行", "C. 4行", "D. 5行"], "a": "C", "e": "FASTQ文件中一个read通常由四行组成：第一行以@开头，为序列标识符及描述信息；第二行为read的序列信息；第三行以+开头，可再次添加序列描述信息（可选）；第四行为质量得分信息，长度必须与第二行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_mcq_6", "mod": "第六章 转录组学", "modI": 0, "q": "在差异表达分析中，负二项分布相比泊松分布的优势是什么？", "o": ["A. 更简单", "B. 可以拟合基因表达方差远大于均值的情况", "C. 不需要生物学重复", "D. 计算速度更快"], "a": "B", "e": "负二项分布的方差可以通过调整散度因子α的值来调节模型的离散度，使其符合实际情况中基因表达方差远大于均值的情况。泊松分布模型可能严重低估个体差异带来的误差。", "kp": "ch06_s0_11"}, {"id": "ch06_mcq_7", "mod": "第六章 转录组学", "modI": 0, "q": "以下哪个工具采用β负二项分布进行差异表达分析？", "o": ["A. DESeq", "B. edgeR", "C. Cuffdiff", "D. limma"], "a": "C", "e": "Cuffdiff采用β负二项分布，该分布可以拟合比对过程中的多重比对reads分配误差，与负二项分布结合而成。DESeq和edgeR采用负二项分布，limma采用线性模型。", "kp": "ch06_s0_11"}, {"id": "ch06_mcq_8", "mod": "第六章 转录组学", "modI": 0, "q": "Trinity软件中，负责将contigs聚类并构建de Bruijn图的模块是？", "o": ["A. Inchworm", "B. Chrysalis", "C. Butterfly", "D. Bowtie"], "a": "B", "e": "Trinity包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图为线性序列，得到全长转录本。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_9", "mod": "第六章 转录组学", "modI": 0, "q": "在RNA-seq数据分析中，用于检测原始测序数据质量的工具是？", "o": ["A. fastq-dump", "B. FastQC", "C. fastx_trimmer", "D. fastq_quality_filter"], "a": "B", "e": "FastQC用于检测原始测序数据质量。fastq-dump用于从SRA文件中提取fastq序列文件；fastx_trimmer用于截去reads前几位碱基；fastq_quality_filter用于过滤低质量reads。", "kp": "ch06_s0_31"}, {"id": "ch06_mcq_10", "mod": "第六章 转录组学", "modI": 0, "q": "关于RNA-seq与多组学结合分析，以下描述错误的是？", "o": ["A. 结合全基因组测序数据可以探测SNP和eQTL", "B. 结合DNA表观修饰数据可以探究表观修饰对差异表达基因的影响", "C. RNA-seq与蛋白质组学数据相关性很高，可直接整合", "D. 结合ChIP-seq可以研究转录因子调节基因表达的动态规律"], "a": "C", "e": "RNA-seq与蛋白质组学数据的相关性较低，具体应用需要慎重考虑。其他选项描述正确：结合全基因组测序可探测SNP和eQTL；结合DNA表观修饰数据可探究表观修饰对差异表达基因的影响；结合ChIP-seq可研究转录因子调节基因表达的动态规律。", "kp": "ch06_s0_20"}], "judge": [{"id": "ch06_judge_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "a": "对", "e": "讲义明确指出中心法则由Crick于1958年提出，描述DNA经RNA到蛋白质的信息流。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。", "a": "对", "e": "转录组学在20世纪90年代提出，研究对象为全基因组尺度下所有转录本，即转录组。", "kp": "ch06_s0_1"}, {"id": "ch06_judge_3", "modI": 0, "q": "RNA-seq必须依赖参考基因组才能直接测定转录本序列和含量。", "a": "错", "e": "RNA-seq不依赖参考基因组，可直接测定转录本序列和含量；无参考基因组时也可进行从头组装。", "kp": "ch06_s0_31"}, {"id": "ch06_judge_4", "modI": 0, "q": "基因芯片技术存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。", "a": "对", "e": "讲义明确列出基因芯片的这些缺陷。", "kp": "ch06_s0_24"}, {"id": "ch06_judge_5", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议3~5个，假阳性控制要求高时可适当增加。", "a": "对", "e": "讲义指出没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。", "kp": "ch06_s0_3"}, {"id": "ch06_judge_6", "modI": 0, "q": "FASTQ文件中第四行为质量得分信息，其长度可以与第二行序列长度不同。", "a": "错", "e": "FASTQ第四行质量得分信息与第二行序列相对应，长度必须与第二行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_judge_7", "modI": 0, "q": "使用fastx_trimmer时，参数-Q 33为Illumina编码转换。", "a": "对", "e": "讲义中fastx_trimmer参数说明指出-Q 33为Illumina编码转换。", "kp": "ch06_s0_21"}, {"id": "ch06_judge_8", "modI": 0, "q": "差异表达分析中，无重复样本时差异表达分析结果可靠性下降。", "a": "对", "e": "讲义指出计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_11"}, {"id": "ch06_judge_9", "modI": 0, "q": "DESeq和edgeR都采用高斯分布描述reads频数分布。", "a": "错", "e": "DESeq和edgeR都采用负二项分布描述reads频数分布，而不是高斯分布。", "kp": "ch06_s0_11"}, {"id": "ch06_judge_10", "modI": 0, "q": "WGCNA是加权基因共表达网络分析，可通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块。", "a": "对", "e": "讲义指出WGCNA是常用共表达网络方法，通过相关系数加权构建无尺度网络，识别共表达模块并与表型关联。", "kp": "ch06_s0_16"}], "fill": [{"id": "ch06_fill_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经________传递至蛋白质的流向。", "a": "RNA", "kp": "ch06_s0_0"}, {"id": "ch06_fill_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有________，即转录组。", "a": "转录本", "kp": "ch06_s0_1"}, {"id": "ch06_fill_3", "modI": 0, "q": "RNA-seq与基因芯片相比，通量方面基因芯片较低，RNA-seq________。", "a": "高", "kp": "ch06_s0_20"}, {"id": "ch06_fill_4", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议________个，假阳性控制要求高时可适当增加。", "a": "3~5", "kp": "ch06_s0_3"}, {"id": "ch06_fill_5", "modI": 0, "q": "有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少需要________有效reads（ENCODE推荐）。", "a": "5M", "kp": "ch06_s0_3"}, {"id": "ch06_fill_6", "modI": 0, "q": "FASTQ文件中一个read通常由四行组成：第一行以@开头，第二行为read的序列信息，第三行以________开头，第四行为质量得分信息。", "a": "+", "kp": "ch06_s0_5"}, {"id": "ch06_fill_7", "modI": 0, "q": "使用fastx_trimmer截去reads前12位碱基时，参数________为Illumina编码转换。", "a": "-Q 33", "kp": "ch06_s0_21"}, {"id": "ch06_fill_8", "modI": 0, "q": "差异表达分析中，DESeq和edgeR都采用________分布描述reads频数分布。", "a": "负二项", "kp": "ch06_s0_11"}], "short": [{"id": "ch06_short_1", "modI": 0, "q": "简述RNA-seq与基因芯片相比的主要优势。", "a": "1. 不依赖参考基因组，可直接测定转录本序列和含量；2. 通量极高；3. 成本日益降低，趋向大众化；4. 动态范围依赖测序深度，可更好覆盖低丰度转录本；5. 可发现新转录本、可变剪切和基因融合等。", "kp": "ch06_s0_30"}, {"id": "ch06_short_2", "modI": 0, "q": "简述RNA-seq实验设计需考虑的主要问题。", "a": "1. 生物学重复：一般3~5个，假阳性控制要求高时可增加；2. 样本提取：控制干扰变量，注意提取时间和组织细胞控制，提取后及时冷冻保存；3. 测序深度：有参考基因组且不分析可变剪切或新转录本时每样本最少5M有效reads，鉴定新转录本或无参考基因组时增加，small RNA一般需30M以上有效匹配reads；4. 文库构建：链特异性文库保留方向信息，定量和可变剪切鉴别更准确但价格更高；5. 测序策略：单末端测序更快、价格低，一般足够定量；双末端测序有利于基因注释和转录本异构体发现。", "kp": "ch06_s0_3"}, {"id": "ch06_short_3", "modI": 0, "q": "简述RNA-seq文库制备的主要流程。", "a": "1. 选择感兴趣样本提取RNA；2. 采用PolyA富集或rRNA移除策略分离纯化RNA；3. 随机打碎成短片段并反转录为cDNA；4. 选择合适长度片段添加接头构建文库；5. 扩增并测序。cDNA文库制备关键步骤包括总RNA提取、RNA分离纯化、cDNA合成。", "kp": "ch06_s0_4"}, {"id": "ch06_short_4", "modI": 0, "q": "简述差异表达分析中差异的来源及处理效应检验的基本思路。", "a": "1. 不同实验处理引起的差异称为处理差异；2. 同一实验条件下不同样本之间由于个体差异、技术误差等存在差异，称为组内差异；3. 直接比较组间差异时包括组内差异和处理差异；4. 最终检验处理效应显著性时，应由组间差异减去组内差异；5. 计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_11"}, {"id": "ch06_short_5", "modI": 0, "q": "简述常用差异表达分析模型及其适用性。", "a": "1. 高斯分布：最初用于描述表达水平，但基因表达量不可能是负值，严格意义上不符合正态分布；2. 泊松分布：技术重复条件下测序方差与泊松分布方差吻合，低表达基因方差符合泊松分布，但表达量升高后实际方差远大于泊松分布方差；3. 负二项分布：可调整散度因子α调节模型离散度，符合基因表达方差远大于均值的情况，DESeq和edgeR采用；4. β负二项分布：可拟合多重比对reads分配误差，与负二项分布结合，Cuffdiff采用。", "kp": "ch06_s0_11"}], "calc": [{"id": "ch06_calc_1", "modI": 0, "q": "论述RNA-seq数据分析中，有参考基因组和无参考基因组两种策略的主要流程差异，并说明各自常用工具。", "a": "有参考基因组时，RNA-seq核心分析通常包括序列比对和表达定量。可使用Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组；随后利用HTSeq-count或RSEM等进行reads计数并估算表达量；还可进行可变剪切、基因融合和差异表达分析。无参考基因组时，需先进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块：Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图并依据reads和成对reads寻找最佳路径，得到具有可变剪切的全长转录本。组装完成后需评估质量，包括组装完整性、准确性及冗余度；再将reads通过Bowtie重新比对到组装转录本上，利用HTSeq-count或RSEM等计数估算表达量，并可通过Blast2GO等进行功能注释。", "steps": "1. 有参考基因组：比对到参考基因组/转录组；2. 常用比对工具：Bowtie、HISAT2、STAR；3. 定量工具：HTSeq-count、RSEM；4. 无参考基因组：从头组装；5. Trinity三模块：Inchworm、Chrysalis、Butterfly；6. 组装质量评估：完整性、准确性、冗余度；7. 重新比对与定量；8. 功能注释：Blast2GO等。", "kp": "ch06_s0_31"}, {"id": "ch06_calc_2", "modI": 0, "q": "结合案例，论述RNA-seq数据预处理与质控的主要步骤、常用命令参数及质控结果解读。", "a": "案例中RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。首先使用fastq-dump工具从SRA文件中提取fastq序列文件，如$ fastq-dump SRR3418005.sra &，对其余文件执行相同命令。然后使用FastQC检测原始测序数据质量，如$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq SRR3418019.fastq SRR3418020.fastq &，其中-o指定输出目录，-f指定输入格式。根据FastQC结果，Per base sequence quality评估为正常，而Per base sequence content显示约前12位碱基核酸比例失常。若测序质量要求较高，可使用FastX_Toolkit进行质量控制：使用fastx_trimmer截去reads前12位碱基，如$ fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq &，其中-Q为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件；使用fastq_quality_filter过滤低质量reads，如$ fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq &，其中-q为保留结果所需达到的最低得分，-p为每个reads中达到-q得分的最小百分数。处理后再次质量评估，Per base sequence content等指标提升，Sequence duplication levels和Kmer Content可能仍未达标，但已可用于RNA-seq分析。", "steps": "1. fastq-dump提取fastq；2. FastQC质量评估；3. 关键指标：Per base sequence quality、Per base sequence content；4. fastx_trimmer截去前12位碱基；5. 参数：-Q 33、-f、-i、-o；6. fastq_quality_filter过滤低质量reads；7. 参数：-q、-p；8. 处理后复评；9. 部分指标提升，部分未达标但可用于分析。", "kp": "ch06_s0_21"}], "term": [{"id": "ch06_term_1", "modI": 0, "term": "Central Dogma", "def": "由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的基本流向；对应三个组学层次：基因组学、转录组学和蛋白质组学。", "kp": "ch06_s0_21"}, {"id": "ch06_term_2", "modI": 0, "term": "Transcriptomics", "def": "20世纪90年代提出，在转录组水平研究基因表达；研究对象是全基因组尺度下所有转录本（transcriptome）。广义包括mRNA、rRNA、tRNA、ncRNA等，狭义常特指mRNA。", "kp": "ch06_s0_13"}, {"id": "ch06_term_3", "modI": 0, "term": "Transcriptome", "def": "细胞或组织中所有RNA分子的总和；包括mRNA、rRNA、tRNA、ncRNA等；本章无特殊说明时专指mRNA。", "kp": "ch06_s0_13"}, {"id": "ch06_term_4", "modI": 0, "term": "RNA-seq", "def": "基于第二代测序的转录组测序技术；不依赖参考基因组即可直接测定转录本序列和含量；通量高、成本日益降低；自2008年Nagalakshmi等用于酵母转录组研究后广泛应用。", "kp": "ch06_s0_2"}, {"id": "ch06_term_5", "modI": 0, "term": "Microarray", "def": "基于杂交的基因芯片技术；将荧光标记cDNA制成微阵列探针；通量较高、价格相对较低；但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态范围有限等缺陷。", "kp": "ch06_s0_23"}, {"id": "ch06_term_6", "modI": 0, "term": "FASTQ", "def": "存储生物序列及其测序质量得分的文本格式；最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及质量数据；现为高通量测序仪输出实际标准。每个read通常四行：@标识行、序列行、+行、质量得分行；质量行长度必须与序列行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_term_7", "modI": 0, "term": "FastQC", "def": "用于检测原始测序数据质量的工具；关键指标包括Per base sequence quality、Per base sequence content等；用于RNA-seq数据预处理中的质量评估。", "kp": "ch06_s0_6"}, {"id": "ch06_term_8", "modI": 0, "term": "FastX_Toolkit", "def": "用于测序数据质量控制的工具集；常用fastx_trimmer截去reads前12位碱基，fastq_quality_filter过滤低质量reads；参数-Q 33用于Illumina编码转换。", "kp": "ch06_s0_6"}, {"id": "ch06_term_9", "modI": 0, "term": "Bowtie", "def": "短序列比对工具；有参考基因组时可将RNA-seq reads比对到参考基因组或转录组；组装后也可将reads重新比对到组装转录本上用于表达定量。", "kp": "ch06_s0_7"}, {"id": "ch06_term_10", "modI": 0, "term": "HISAT2", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组，用于后续表达定量和可变剪切分析。", "kp": "ch06_s0_22"}, {"id": "ch06_term_11", "modI": 0, "term": "STAR", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组；也常用于基因融合分析相关流程。", "kp": "ch06_s0_5"}, {"id": "ch06_term_12", "modI": 0, "term": "Trinity", "def": "无参考基因组时进行从头组装的软件；包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis聚类contigs并构建de Bruijn图；Butterfly拆分de Bruijn图并寻找最佳路径，得到具有可变剪切的全长转录本。", "kp": "ch06_s0_24"}]}], "mcq": [{"id": "ch06_mcq_1", "mod": "第六章 转录组学", "modI": 0, "q": "关于转录组学，以下描述正确的是？", "o": ["A. 转录组学的研究对象是基因组DNA", "B. 转录组学一词最早在20世纪90年代提出", "C. 转录组仅指mRNA", "D. 转录组学从蛋白质水平研究基因表达"], "a": "B", "e": "转录组学一词最早在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。广义上转录组包括mRNA、rRNA、tRNA、ncRNA等，但有时特指mRNA。转录组学从RNA水平研究基因表达。", "kp": "ch06_s0_0"}, {"id": "ch06_mcq_2", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq与基因芯片相比，以下哪项不是RNA-seq的优势？", "o": ["A. 不依赖于参考基因组", "B. 可以直接测定转录本序列和含量", "C. 通量极高", "D. 荧光信号动态检测范围有限"], "a": "D", "e": "荧光信号动态检测范围有限是基因芯片的缺陷，不是RNA-seq的优势。RNA-seq的优势包括不依赖参考基因组、直接测定转录本序列和含量、通量极高、成本日益降低等。", "kp": "ch06_s0_2"}, {"id": "ch06_mcq_3", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq试验设计中，对于有参考基因组且不进行可变剪切或新转录本分析的情况，每个样本最少需要多少有效reads？", "o": ["A. 1M", "B. 5M", "C. 10M", "D. 30M"], "a": "B", "e": "根据ENCODE推荐，有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少只需要5M的有效reads。small RNA一般需要30M以上的有效匹配reads。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_4", "mod": "第六章 转录组学", "modI": 0, "q": "关于链特异性文库，以下描述正确的是？", "o": ["A. 无法区分转录本来源", "B. 保留了转录本的方向信息", "C. 价格比非链特异性文库低", "D. 不利于可变剪切鉴别"], "a": "B", "e": "链特异性文库在建库时保留了转录本的方向信息，用以区分转录本来源，避免互补链干扰。相较于非链特异性文库，基因表达定量和可变剪切鉴别更准确，但价格更高。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_5", "mod": "第六章 转录组学", "modI": 0, "q": "FASTQ文件中，一个read通常由几行组成？", "o": ["A. 2行", "B. 3行", "C. 4行", "D. 5行"], "a": "C", "e": "FASTQ文件中一个read通常由四行组成：第一行以@开头，为序列标识符及描述信息；第二行为read的序列信息；第三行以+开头，可再次添加序列描述信息（可选）；第四行为质量得分信息，长度必须与第二行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_mcq_6", "mod": "第六章 转录组学", "modI": 0, "q": "在差异表达分析中，负二项分布相比泊松分布的优势是什么？", "o": ["A. 更简单", "B. 可以拟合基因表达方差远大于均值的情况", "C. 不需要生物学重复", "D. 计算速度更快"], "a": "B", "e": "负二项分布的方差可以通过调整散度因子α的值来调节模型的离散度，使其符合实际情况中基因表达方差远大于均值的情况。泊松分布模型可能严重低估个体差异带来的误差。", "kp": "ch06_s0_11"}, {"id": "ch06_mcq_7", "mod": "第六章 转录组学", "modI": 0, "q": "以下哪个工具采用β负二项分布进行差异表达分析？", "o": ["A. DESeq", "B. edgeR", "C. Cuffdiff", "D. limma"], "a": "C", "e": "Cuffdiff采用β负二项分布，该分布可以拟合比对过程中的多重比对reads分配误差，与负二项分布结合而成。DESeq和edgeR采用负二项分布，limma采用线性模型。", "kp": "ch06_s0_11"}, {"id": "ch06_mcq_8", "mod": "第六章 转录组学", "modI": 0, "q": "Trinity软件中，负责将contigs聚类并构建de Bruijn图的模块是？", "o": ["A. Inchworm", "B. Chrysalis", "C. Butterfly", "D. Bowtie"], "a": "B", "e": "Trinity包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图为线性序列，得到全长转录本。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_9", "mod": "第六章 转录组学", "modI": 0, "q": "在RNA-seq数据分析中，用于检测原始测序数据质量的工具是？", "o": ["A. fastq-dump", "B. FastQC", "C. fastx_trimmer", "D. fastq_quality_filter"], "a": "B", "e": "FastQC用于检测原始测序数据质量。fastq-dump用于从SRA文件中提取fastq序列文件；fastx_trimmer用于截去reads前几位碱基；fastq_quality_filter用于过滤低质量reads。", "kp": "ch06_s0_31"}, {"id": "ch06_mcq_10", "mod": "第六章 转录组学", "modI": 0, "q": "关于RNA-seq与多组学结合分析，以下描述错误的是？", "o": ["A. 结合全基因组测序数据可以探测SNP和eQTL", "B. 结合DNA表观修饰数据可以探究表观修饰对差异表达基因的影响", "C. RNA-seq与蛋白质组学数据相关性很高，可直接整合", "D. 结合ChIP-seq可以研究转录因子调节基因表达的动态规律"], "a": "C", "e": "RNA-seq与蛋白质组学数据的相关性较低，具体应用需要慎重考虑。其他选项描述正确：结合全基因组测序可探测SNP和eQTL；结合DNA表观修饰数据可探究表观修饰对差异表达基因的影响；结合ChIP-seq可研究转录因子调节基因表达的动态规律。", "kp": "ch06_s0_20"}], "judge": [{"id": "ch06_judge_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "a": "对", "e": "讲义明确指出中心法则由Crick于1958年提出，描述DNA经RNA到蛋白质的信息流。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。", "a": "对", "e": "转录组学在20世纪90年代提出，研究对象为全基因组尺度下所有转录本，即转录组。", "kp": "ch06_s0_1"}, {"id": "ch06_judge_3", "modI": 0, "q": "RNA-seq必须依赖参考基因组才能直接测定转录本序列和含量。", "a": "错", "e": "RNA-seq不依赖参考基因组，可直接测定转录本序列和含量；无参考基因组时也可进行从头组装。", "kp": "ch06_s0_31"}, {"id": "ch06_judge_4", "modI": 0, "q": "基因芯片技术存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。", "a": "对", "e": "讲义明确列出基因芯片的这些缺陷。", "kp": "ch06_s0_24"}, {"id": "ch06_judge_5", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议3~5个，假阳性控制要求高时可适当增加。", "a": "对", "e": "讲义指出没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。", "kp": "ch06_s0_3"}, {"id": "ch06_judge_6", "modI": 0, "q": "FASTQ文件中第四行为质量得分信息，其长度可以与第二行序列长度不同。", "a": "错", "e": "FASTQ第四行质量得分信息与第二行序列相对应，长度必须与第二行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_judge_7", "modI": 0, "q": "使用fastx_trimmer时，参数-Q 33为Illumina编码转换。", "a": "对", "e": "讲义中fastx_trimmer参数说明指出-Q 33为Illumina编码转换。", "kp": "ch06_s0_21"}, {"id": "ch06_judge_8", "modI": 0, "q": "差异表达分析中，无重复样本时差异表达分析结果可靠性下降。", "a": "对", "e": "讲义指出计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_11"}, {"id": "ch06_judge_9", "modI": 0, "q": "DESeq和edgeR都采用高斯分布描述reads频数分布。", "a": "错", "e": "DESeq和edgeR都采用负二项分布描述reads频数分布，而不是高斯分布。", "kp": "ch06_s0_11"}, {"id": "ch06_judge_10", "modI": 0, "q": "WGCNA是加权基因共表达网络分析，可通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块。", "a": "对", "e": "讲义指出WGCNA是常用共表达网络方法，通过相关系数加权构建无尺度网络，识别共表达模块并与表型关联。", "kp": "ch06_s0_16"}], "fill": [{"id": "ch06_fill_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经________传递至蛋白质的流向。", "a": "RNA", "kp": "ch06_s0_0"}, {"id": "ch06_fill_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有________，即转录组。", "a": "转录本", "kp": "ch06_s0_1"}, {"id": "ch06_fill_3", "modI": 0, "q": "RNA-seq与基因芯片相比，通量方面基因芯片较低，RNA-seq________。", "a": "高", "kp": "ch06_s0_20"}, {"id": "ch06_fill_4", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议________个，假阳性控制要求高时可适当增加。", "a": "3~5", "kp": "ch06_s0_3"}, {"id": "ch06_fill_5", "modI": 0, "q": "有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少需要________有效reads（ENCODE推荐）。", "a": "5M", "kp": "ch06_s0_3"}, {"id": "ch06_fill_6", "modI": 0, "q": "FASTQ文件中一个read通常由四行组成：第一行以@开头，第二行为read的序列信息，第三行以________开头，第四行为质量得分信息。", "a": "+", "kp": "ch06_s0_5"}, {"id": "ch06_fill_7", "modI": 0, "q": "使用fastx_trimmer截去reads前12位碱基时，参数________为Illumina编码转换。", "a": "-Q 33", "kp": "ch06_s0_21"}, {"id": "ch06_fill_8", "modI": 0, "q": "差异表达分析中，DESeq和edgeR都采用________分布描述reads频数分布。", "a": "负二项", "kp": "ch06_s0_11"}], "short": [{"id": "ch06_short_1", "modI": 0, "q": "简述RNA-seq与基因芯片相比的主要优势。", "a": "1. 不依赖参考基因组，可直接测定转录本序列和含量；2. 通量极高；3. 成本日益降低，趋向大众化；4. 动态范围依赖测序深度，可更好覆盖低丰度转录本；5. 可发现新转录本、可变剪切和基因融合等。", "kp": "ch06_s0_30"}, {"id": "ch06_short_2", "modI": 0, "q": "简述RNA-seq实验设计需考虑的主要问题。", "a": "1. 生物学重复：一般3~5个，假阳性控制要求高时可增加；2. 样本提取：控制干扰变量，注意提取时间和组织细胞控制，提取后及时冷冻保存；3. 测序深度：有参考基因组且不分析可变剪切或新转录本时每样本最少5M有效reads，鉴定新转录本或无参考基因组时增加，small RNA一般需30M以上有效匹配reads；4. 文库构建：链特异性文库保留方向信息，定量和可变剪切鉴别更准确但价格更高；5. 测序策略：单末端测序更快、价格低，一般足够定量；双末端测序有利于基因注释和转录本异构体发现。", "kp": "ch06_s0_3"}, {"id": "ch06_short_3", "modI": 0, "q": "简述RNA-seq文库制备的主要流程。", "a": "1. 选择感兴趣样本提取RNA；2. 采用PolyA富集或rRNA移除策略分离纯化RNA；3. 随机打碎成短片段并反转录为cDNA；4. 选择合适长度片段添加接头构建文库；5. 扩增并测序。cDNA文库制备关键步骤包括总RNA提取、RNA分离纯化、cDNA合成。", "kp": "ch06_s0_4"}, {"id": "ch06_short_4", "modI": 0, "q": "简述差异表达分析中差异的来源及处理效应检验的基本思路。", "a": "1. 不同实验处理引起的差异称为处理差异；2. 同一实验条件下不同样本之间由于个体差异、技术误差等存在差异，称为组内差异；3. 直接比较组间差异时包括组内差异和处理差异；4. 最终检验处理效应显著性时，应由组间差异减去组内差异；5. 计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_11"}, {"id": "ch06_short_5", "modI": 0, "q": "简述常用差异表达分析模型及其适用性。", "a": "1. 高斯分布：最初用于描述表达水平，但基因表达量不可能是负值，严格意义上不符合正态分布；2. 泊松分布：技术重复条件下测序方差与泊松分布方差吻合，低表达基因方差符合泊松分布，但表达量升高后实际方差远大于泊松分布方差；3. 负二项分布：可调整散度因子α调节模型离散度，符合基因表达方差远大于均值的情况，DESeq和edgeR采用；4. β负二项分布：可拟合多重比对reads分配误差，与负二项分布结合，Cuffdiff采用。", "kp": "ch06_s0_11"}], "calc": [{"id": "ch06_calc_1", "modI": 0, "q": "论述RNA-seq数据分析中，有参考基因组和无参考基因组两种策略的主要流程差异，并说明各自常用工具。", "a": "有参考基因组时，RNA-seq核心分析通常包括序列比对和表达定量。可使用Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组；随后利用HTSeq-count或RSEM等进行reads计数并估算表达量；还可进行可变剪切、基因融合和差异表达分析。无参考基因组时，需先进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块：Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图并依据reads和成对reads寻找最佳路径，得到具有可变剪切的全长转录本。组装完成后需评估质量，包括组装完整性、准确性及冗余度；再将reads通过Bowtie重新比对到组装转录本上，利用HTSeq-count或RSEM等计数估算表达量，并可通过Blast2GO等进行功能注释。", "steps": "1. 有参考基因组：比对到参考基因组/转录组；2. 常用比对工具：Bowtie、HISAT2、STAR；3. 定量工具：HTSeq-count、RSEM；4. 无参考基因组：从头组装；5. Trinity三模块：Inchworm、Chrysalis、Butterfly；6. 组装质量评估：完整性、准确性、冗余度；7. 重新比对与定量；8. 功能注释：Blast2GO等。", "kp": "ch06_s0_31"}, {"id": "ch06_calc_2", "modI": 0, "q": "结合案例，论述RNA-seq数据预处理与质控的主要步骤、常用命令参数及质控结果解读。", "a": "案例中RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。首先使用fastq-dump工具从SRA文件中提取fastq序列文件，如$ fastq-dump SRR3418005.sra &，对其余文件执行相同命令。然后使用FastQC检测原始测序数据质量，如$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq SRR3418019.fastq SRR3418020.fastq &，其中-o指定输出目录，-f指定输入格式。根据FastQC结果，Per base sequence quality评估为正常，而Per base sequence content显示约前12位碱基核酸比例失常。若测序质量要求较高，可使用FastX_Toolkit进行质量控制：使用fastx_trimmer截去reads前12位碱基，如$ fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq &，其中-Q为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件；使用fastq_quality_filter过滤低质量reads，如$ fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq &，其中-q为保留结果所需达到的最低得分，-p为每个reads中达到-q得分的最小百分数。处理后再次质量评估，Per base sequence content等指标提升，Sequence duplication levels和Kmer Content可能仍未达标，但已可用于RNA-seq分析。", "steps": "1. fastq-dump提取fastq；2. FastQC质量评估；3. 关键指标：Per base sequence quality、Per base sequence content；4. fastx_trimmer截去前12位碱基；5. 参数：-Q 33、-f、-i、-o；6. fastq_quality_filter过滤低质量reads；7. 参数：-q、-p；8. 处理后复评；9. 部分指标提升，部分未达标但可用于分析。", "kp": "ch06_s0_21"}], "term": [{"id": "ch06_term_1", "modI": 0, "term": "Central Dogma", "def": "由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的基本流向；对应三个组学层次：基因组学、转录组学和蛋白质组学。", "kp": "ch06_s0_21"}, {"id": "ch06_term_2", "modI": 0, "term": "Transcriptomics", "def": "20世纪90年代提出，在转录组水平研究基因表达；研究对象是全基因组尺度下所有转录本（transcriptome）。广义包括mRNA、rRNA、tRNA、ncRNA等，狭义常特指mRNA。", "kp": "ch06_s0_13"}, {"id": "ch06_term_3", "modI": 0, "term": "Transcriptome", "def": "细胞或组织中所有RNA分子的总和；包括mRNA、rRNA、tRNA、ncRNA等；本章无特殊说明时专指mRNA。", "kp": "ch06_s0_13"}, {"id": "ch06_term_4", "modI": 0, "term": "RNA-seq", "def": "基于第二代测序的转录组测序技术；不依赖参考基因组即可直接测定转录本序列和含量；通量高、成本日益降低；自2008年Nagalakshmi等用于酵母转录组研究后广泛应用。", "kp": "ch06_s0_2"}, {"id": "ch06_term_5", "modI": 0, "term": "Microarray", "def": "基于杂交的基因芯片技术；将荧光标记cDNA制成微阵列探针；通量较高、价格相对较低；但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态范围有限等缺陷。", "kp": "ch06_s0_23"}, {"id": "ch06_term_6", "modI": 0, "term": "FASTQ", "def": "存储生物序列及其测序质量得分的文本格式；最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及质量数据；现为高通量测序仪输出实际标准。每个read通常四行：@标识行、序列行、+行、质量得分行；质量行长度必须与序列行相同。", "kp": "ch06_s0_5"}, {"id": "ch06_term_7", "modI": 0, "term": "FastQC", "def": "用于检测原始测序数据质量的工具；关键指标包括Per base sequence quality、Per base sequence content等；用于RNA-seq数据预处理中的质量评估。", "kp": "ch06_s0_6"}, {"id": "ch06_term_8", "modI": 0, "term": "FastX_Toolkit", "def": "用于测序数据质量控制的工具集；常用fastx_trimmer截去reads前12位碱基，fastq_quality_filter过滤低质量reads；参数-Q 33用于Illumina编码转换。", "kp": "ch06_s0_6"}, {"id": "ch06_term_9", "modI": 0, "term": "Bowtie", "def": "短序列比对工具；有参考基因组时可将RNA-seq reads比对到参考基因组或转录组；组装后也可将reads重新比对到组装转录本上用于表达定量。", "kp": "ch06_s0_7"}, {"id": "ch06_term_10", "modI": 0, "term": "HISAT2", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组，用于后续表达定量和可变剪切分析。", "kp": "ch06_s0_22"}, {"id": "ch06_term_11", "modI": 0, "term": "STAR", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组；也常用于基因融合分析相关流程。", "kp": "ch06_s0_5"}, {"id": "ch06_term_12", "modI": 0, "term": "Trinity", "def": "无参考基因组时进行从头组装的软件；包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis聚类contigs并构建de Bruijn图；Butterfly拆分de Bruijn图并寻找最佳路径，得到具有可变剪切的全长转录本。", "kp": "ch06_s0_24"}], "preview": {"main": "本章围绕转录组学展开，从中心法则和转录组学概述出发，介绍RNA-seq试验设计、测序流程与数据质控，进而讲解剪接比对、转录本定量、标准化和差异表达分析，最后延伸到功能分析、共表达网络、多组学整合及完整RNA-seq数据分析案例。", "questions": ["转录组学在中心法则和三大组学层次中处于什么位置？其研究目标是什么？", "RNA-seq实验设计为什么强调生物学重复？样本提取和测序平台选择需要考虑哪些关键因素？", "真核生物RNA-seq数据为什么需要剪接比对？常用剪接比对工具有哪些，各有什么特点？", "差异表达分析中泊松分布与负二项分布有何区别？DESeq2和edgeR的标准化与统计模型有何异同？", "获得差异表达基因后，如何通过GO/KEGG富集、GSEA和WGCNA共表达网络挖掘关键功能模块与核心基因？"]}, "appcards": [{"front": "应用/分析型问题：某研究拟比较野生型与突变体拟南芥在脱落酸处理下的基因表达差异，请设计一个完整的RNA-seq实验方案，并说明关键质控与差异表达分析要点。", "back": "1. 实验设计：设置野生型和突变体两组，每组至少3个生物学重复，ABA处理与对照条件一致，控制提取时间、组织部位，提取后及时冷冻。2. 建库测序：提取总RNA，去除rRNA，片段化并逆转录为cDNA，选择Illumina平台，考虑读长、通量和准确率。3. 质控：FastQC检查Per base sequence quality、GC含量、接头污染等，必要时用Trimmomatic等去接头和低质量碱基。4. 比对与定量：有参分析用HISAT2剪接比对到参考基因组，SAM转BAM并排序，用StringTie或featureCounts定量。5. 差异表达：采用DESeq2或edgeR，基于负二项分布，进行标准化和统计检验，获得差异表达基因。6. 功能分析：对差异基因做GO/KEGG富集，必要时用WGCNA构建共表达网络，挖掘关键模块和hub基因。", "points": "生物学重复3~5个；rRNA去除；FastQC质控；HISAT2剪接比对；负二项分布模型；DESeq2/edgeR；GO/KEGG富集；WGCNA共表达网络", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：真核生物mRNA的reads可能跨越外显子-外显子连接处，为什么普通比对工具不合适？应如何选择剪接比对工具并评估比对结果？", "back": "1. 原因：真核生物mRNA成熟后内含子被剪接，reads可能跨越外显子-外显子连接处，而参考基因组包含内含子，普通比对工具无法将跨越剪接位点的reads连续比对到基因组。2. 剪接比对：需将reads分段比对到剪接点两侧的外显子上，常用工具包括TopHat、STAR和HISAT。TopHat2先利用Bowtie比对，再识别剪接位点；STAR和HISAT速度更快、内存需求不同。3. 比对评估：可用RSeQC和Qualimap评估reads在参考基因组上的分布，分布均匀说明RNA打断随机性较好；匹配reads的GC含量与PCR偏差有关。4. 结果格式：比对结果通常以SAM/BAM格式存储，包含比对位置、CIGAR字符串等信息，可进一步用于定量和可视化。", "points": "跨越外显子-外显子连接处；参考基因组含内含子；剪接比对分段比对；TopHat/STAR/HISAT；RSeQC/Qualimap；reads分布均匀性；GC含量与PCR偏差；SAM/BAM格式", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：RNA-seq差异表达分析中，为什么常用负二项分布而不是泊松分布？请比较DESeq2和edgeR的标准化与统计模型，并说明如何控制假阳性。", "back": "1. 泊松分布假设均值等于方差，但实际RNA-seq基因表达方差常远大于均值，存在过离散，因此泊松分布拟合不佳。2. 负二项分布通过散度因子调节离散度，更符合实际计数数据，DESeq和edgeR均采用负二项分布。3. DESeq2使用DESeq sizeFactors进行标准化，基于负二项广义线性模型，经验贝叶斯收缩估计离散度。4. edgeR采用TMM校正方法，通过去除高表达和高差异基因后计算加权系数，使剩余基因校正后差异倍数尽可能小，结果较稳定，但未校正基因长度影响。5. 控制假阳性：设置合适的生物学重复，一般3~5个，假阳性控制要求高时可增加重复；使用Benjamini-Hochberg等方法校正p值，控制FDR；结合fold change阈值和功能分析验证。", "points": "泊松分布均值等于方差；实际数据过离散；负二项分布散度因子；DESeq2 sizeFactors；edgeR TMM；经验贝叶斯离散度估计；生物学重复3~5个；FDR校正", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：获得差异表达基因后，如何通过富集分析和共表达网络挖掘关键功能模块与核心基因？请以WGCNA为例说明主要步骤和读图要点。", "back": "1. 富集分析：对差异显著基因做GO和KEGG富集，常用工具包括clusterProfiler、DAVID、IPA、GSEA等。GSEA根据基因表达量与样本表型的相关性排序，判断基因集是否集中于排序列表顶部或底部，计算富集分数ES并评估显著性。2. 共表达网络：利用功能相关基因在特定环境下协调表达的特点，构建基因共表达网络。WGCNA是常用方法。3. WGCNA步骤：样本层次聚类检查异常样本；选择软阈值使网络符合无标度分布；构建加权邻接矩阵并转换为TOM；层次聚类划分模块；计算模块特征基因ME；对ME聚类合并相似模块；绘制模块-性状关系热图。4. 读图要点：模块特征基因聚类树中距离越近的模块表达模式越相似；模块-性状关系热图中颜色深浅表示模块与表型相关性及显著性；节点半径越大表示总连通性越高，可能处于调控枢纽位置；高度连接的基因称为hub基因，可优先作为关键候选基因。", "points": "GO/KEGG富集；GSEA富集分数ES；WGCNA；样本聚类检查异常；软阈值选择；TOM矩阵；模块划分；模块特征基因ME；模块-性状关系热图；hub基因", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}]};